INSERT INTO wiki_pages (path,title,summary,commit_sha,content_sha,updated_at,metadata_json) VALUES ('wiki/sources/zwischenstand-zur-beabsichtigten-wiedereinfuhrung-von-rahmenvertragen-zum-fahrplan-2029-ff.md','Zwischenstand zur beabsichtigten WiedereinfÃ¼hrung von RahmenvertrÃ¤gen zum Fahrplan 2029 ff.','28\. Mai 2026, 14:00 Uhr Mit Kund:inneninformation vom 21. April 2026 haben wir aufgrund aktueller Diskussionen zum Zeitpunkt einer WiedereinfÃ¼hrung von RahmenvertrÃ¤gen kurzfristig um Feedback der Zugangsberechtigten bis 30. April 2026 gebeten. Zur Auswahl wurden zwei sinnvolle Optionen gestellt: - Option 1: WiedereinfÃ¼hrung der RahmenvertrÃ¤ge zum Netzfahrpl','bootstrap:8167d6e7e0c67277823535238e2de902fd05f9a26c8361e8c46f513f4d612747','0c3e2d8f0bb23a5b1facb28db6d0368c9cdfc9872b7b36534cb2e5cb18f12796','2026-08-08T16:35:02Z','{"bootstrap":true,"canonical_url":"https://www.dbinfrago.com/web/aktuelles/kund-inneninformationen/kund-inneninformationen/2026-KW22-Zwischenstand-Wiedereinfuehrung-Rahmenvertraege-Fpl29-13885116","license":"unknown","origin_page_url":"https://www.dbinfrago.com/web/aktuelles/kund-inneninformationen/kund-inneninformationen/2026-KW22-Zwischenstand-Wiedereinfuehrung-Rahmenvertraege-Fpl29-13885116","source_id":"src_9a2a1d3874887b8047bf","source_version_id":"sv_525c1a9f54d50c8af1aaceb9"}') ON CONFLICT(path) DO UPDATE SET title=excluded.title,summary=excluded.summary,commit_sha=excluded.commit_sha,content_sha=excluded.content_sha,updated_at=excluded.updated_at,metadata_json=excluded.metadata_json;
