INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_b0be506b825c21016e8b93af","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",0,"Seite 1","I.NPB 2 (B)\n\nFragenkatalog ANNEX VII\n\n4. Konsultationsphase\n\nStand vom 31.07.2026\n\nDB InfraGO AG\n\nErsteller: V.IWF 41\n\n31.07.2026\n\nVersion 4.0",20,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":1,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","e308f150bd6d5306bbb69aee6ce968c32886a1fbe02565ae5abee56d04a72c4f"],["chunk_7f8492649e71145145bbf529","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",1,"Seite 2","Inhaltsverzeichnis\n\nAllgemein ANNEX VII ................................................................................................................ 3\n\nIT ................................................................................................................................................ 5\n\nNeue Fahrplanprodukte ........................................................................................................... 8\n\nBaubedingte Zusatzleistungen .............................................................................................. 18\n\nÃ„nderungsbestellung ............................................................................................................. 21\n\nInternational ............................................................................................................................ 25\n\nMittiger Teilausfall SEV (Schienenersatzverkehr) ................................................................ 26\n\nDigitale BauFplo ..................................................................................................................... 27\n\nV.IWF 41 Fragenkatalog 2",37,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":2,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","994c6be51a12b9d8afeac666841de9305129b062fcdc2aed59b86b003f8a48bc"],["chunk_996c0943c87a67d81146a49b","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",2,"Seite 3","Allgemein ANNEX VII\n\n1.1 Wie wird ANNEX VII in den DB RegioNetz Verkehrsgesellschaft GmbH und den beiden\n\nGleichstrom Netzen S-Bahn Hamburg und S-Bahn Berlin umgesetzt werden? Werden\n\ndiese genannten Netze identisch zu den anderen DB InfraGO Netzen umgesetzt oder gibt\n\nes hier Abweichungen?\n\nDie INB gelten auch fÃ¼r DB RegioNetz und S-Bahn Netze, der ANNEX VII unterscheidet hier\n\nnicht.\n\n1.2 Wann wird es eine Visualisierung/graphische Darstellung der KonsultationszeitrÃ¤ume\n\nim ANNEX VII geben.\n\nWir werden uns anhand der verÃ¶ffentlichten Terminkalender orientieren und gemÃ¤ÃŸ der Ril.\n\n402.0305 und haben beim Terminkalender eine visualisierte Darstellung fÃ¼r das Jahr 2026 und\n\nseinen jeweiligen Konsultationsphasen hinzugefÃ¼gt.\n\n1.3 Wie wird sichergestellt, dass AufgabentrÃ¤ger die Informationen zum ANNEX VII erhalten und die KOMBau nutzen kÃ¶nnen.\n\nAlle Details zu ANNEX VII sind diskriminierungsfrei auf unserer Website verÃ¶ffentlicht. Um die\n\nLeistungen der DB InfraGO beziehen zu kÃ¶nnen und eine eigene Kundennummer zu erhalten,\n\nist ein G-INV, Grundsatzinfrastrukturnutzungsvertrag erforderlich. Dieser ist jÃ¤hrlich neu abzuschlieÃŸen nach den INB (Infrastrukturnutzungsbedingungen). Sofern kein eigener G-INV vorhanden ist und auch keine Absicht besteht einen eigenen G-INV zu erhalten, kann bei entsprechender Zustimmung ein lesender Zugang Ã¼ber die Kundennummer des EVU eingerichtet werden. Der G-INV ist eine Anlage der INB (Anlage 3.2.1.1) und dort regulÃ¤r zu finden.\n\n1.4 Die parallellaufenden Stellungnahmen in der KOMBau und PlaTo bringt die Regionen,",214,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":3,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","76abbbc63a77064a4dc7c6888b9de6df4b737ea6eb94e65d6b21b6850b484b90"],["chunk_8fb1666ce0261c68c8906a28","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",3,"Seite 3","in der ohnehin angespannten Lage mit Verfristungen von BaumaÃŸnahmen, an ihre Belastungsgrenze. Wie stehen nach EinfÃ¼hrung von Annex VII â€“ KOMBau und PlaTo zueinander? Wo werden in Zukunft Ergebnisse, wie zum Beispiel die AlternativprÃ¼fungen x-33,\n\nkommuniziert und hinterlegt?\n\nPlaTo dient als System fÃ¼r den Ãœbergang bis alle Konsultationsphasen und deren Besonderheiten in der KOMBau vollumfÃ¤nglich abgebildet werden kÃ¶nnen.\n\n1.5 Frage zum betroffenen Verkehrsaufkommen in den BKE-Kategorien. Wenn es sich um\n\nnÃ¤chtliche Sperrungen handelt, wird fÃ¼r die Berechnung der % das Verkehrsaufkommen\n\ndes ganzen Tages zugrunde gelegt oder nur fÃ¼r die Stunden, in denen tatsÃ¤chlich gesperrt ist?\n\nDie KapazitÃ¤tseinschrÃ¤nkung ist Ã¼ber 24 Stunden zu berechnen/anzugeben.\n\nDabei werden die ZÃ¼ge, die durch die Baustelle(n) nicht mehr verkehren kÃ¶nnen, ins VerhÃ¤ltnis\n\nzu den ZÃ¼gen gesetzt, die Ã¼ber 24 Stunden verkehren.\n\nBeispiel:\n\nâ€¢Ãœber 24 Stunden verkehren 100 ZÃ¼ge.\n\nâ€¢Durch eine nÃ¤chtliche TSP (Totalsperrung) sind 25 ZÃ¼ge betroffen. Diese 25 mÃ¼ssten also umgeleitet werden oder ausfallen.\n\nâ€¢25 von 100 sind 25% - somit ergibt sich fÃ¼r den einen Tag eine KapazitÃ¤tseinschrÃ¤nkung von\n\n25%.\n\nDie Vorgehensweise wird in Abschnitt 2 der Richtlinie 402.0305 beschrieben.\n\nV.IWF 41 Fragenkatalog 3",182,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":3,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","3c4a6dfe7dca6ff38492e1c97acffe799b83cd71b81bc40b7469b1e3cf81ff6b"],["chunk_0e1a8edaa3d506fd843ddc4a","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",4,"Seite 4","1.6 Wie granular sollen Stellungnahmen sein? Zu welchem Zeitpunkt soll u.a. die Erreichbarkeit von Serviceeinrichtungen (SE) mit betrachtet werden?\n\nDie DB InfraGO konsultiert BaumaÃŸnahmen nach den Fristen des Annex VII und ist daher bestrebt frÃ¼hzeitig Ã¼ber EinschrÃ¤nkungen zu informieren. Gleisscharfe EinschrÃ¤nkungen an SE\n\nwerden erstmals ab der 2. KP verÃ¶ffentlicht. Sind hier Gleise betroffen, auf denen Sie einen\n\nMehrjahresvertrag haben, bitte wir sie dies in der Stellungnahme mitzuteilen, damit hier zeitnah\n\nnach Ersatz geschaut werden kann.\n\nFalls Sie bereits in der 1. KP feststellen, dass durch BKEn fÃ¼r Sie wichtige SE ggfs. eingeschrÃ¤nkt sind, kÃ¶nnen Sie uns dies natÃ¼rlich gerne mitteilen. Dies kÃ¶nnte dann, sofern mÃ¶glich,\n\nim weiteren Planungsverlauf der MaÃŸnahme berÃ¼cksichtigt werden.\n\nIn jedem Fall ist zu beachten, dass EinschrÃ¤nkungen nach Abschluss einer Konsultationsphase\n\ni.d.R. kein weiteres Mal zu Stellungnahme verÃ¶ffentlicht werden.\n\n1.7 Stellungnahmen, die in Konsultationsphase (KP) 1 abgegeben wurden, sollten/mÃ¼ssen Ã¼ber die einzelnen KP mitgenommen werden kÃ¶nnen bzw. sichtbar sein.\n\nDie Stellungnahme ist immer in dem Zeitpunkt einsehbar in dem diese auch abgegeben wurde.\n\n1.8 Wann erfolgte die unterjÃ¤hrige Anpassung der INB 2027 und welche Themen betraf\n\ndas?\n\nVerÃ¶ffentlichung der Kund:inneninformation war am 12.02.2026. Bis zum 12.03.2026 war Zeit\n\nStellung zu nehmen. Es werden verschiedene Regelungen in der Richtlinie 402.0305 fÃ¼r die\n\nINB 2026 und / oder 2027 Ã¼berarbeitet. FÃ¼r die INB 2026 und 2027 werden der Abschnitt 7 (1)\n\nbzw. Abschnitt 8 (1), Abschnitt 9 (1) bzw. 10 (1) und Abschnitt 16 (1) bzw. 15 (1) geÃ¤ndert. FÃ¼r\n\ndie INB 2027 werden zusÃ¤tzlich die Abschnitte 8 (6), 10 (7) und Abschnitt 16 (1) angepasst.",258,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":4,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","e01509d66eb3b518abca297d72425163f23f9784706d1e55d0d78562454efc6a"],["chunk_232d945f74ef4720b2b27dd9","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",5,"Seite 4","1.9 Welche BKE-Nummern werden dargestellt und wie ist das verbindliche Format?\n\nDie ID''s der 1. Konsultationsphase beschreiben den Bautaktkorridor/die Bauaktphase. Die ID''s\n\nder 2.-4. Konsultationsphase beschreiben die BKE, die aus dem BKE-Verwaltungssystem geliefert werden.\n\n1.10 Kann auf eine bereits abgestimmte BKE 7 aus der 1. und 2. Konsultationsphase in\n\nder 3. Konsultationsphase noch ein BKE 2 folgen?\n\nDer konsultierte Stand der 2.KP geht in den Netzfahrplan und bildet die Grundlage fÃ¼r die Fpl.-\n\nKonzepte der 3.KP. D. h., abgestimmte BKE der 2.KP kÃ¶nnen mit BKE der 3.KP in der 3.KP\n\nbzw. BKE der 4.KP in der 4.KP nochmal zusÃ¤tzlich koordiniert werden.\n\nV.IWF 41 Fragenkatalog 4",105,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":4,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","dbd354b4da665f85a0acbf7d7b5edbe180a278f921839a46ad127cf5dc2b56c5"],["chunk_53255126e6154c3fc87a8239","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",6,"Seite 5","IT\n\n1.1 Ist die EinfÃ¼hrung eines neuen TC-Objektes (Bau ID) fÃ¼r Fplj 2026 vorgesehen\n\nEs handelt sich hierbei nicht um ein neues Objekt, sondern einen neuen Objekttype fÃ¼r die BaumaÃŸnahme. Der Objekttype ist bereits in der xsd vorhanden.\n\n1.2 Wir gehen davon aus, dass die GPE, wenn sie inhaltlich gleich sind, immer in einem\n\nDatensatz/PathRequest geschickt werden.\n\nBei einem GPE handelt es sich nicht um einen PathRequest, sondern eine PathDetailsMessage. Wenn ein Zug im GPE an 7 Tagen gleich ausgeregelt ist, wird ein GPE versendet. Die\n\nStellungnahme (PathRequestMessage) ist ebenfalls gesammelt (also nur eine SN auf ein GPE)\n\nund am Anfang nicht einzeln mÃ¶glich.\n\n1.3 Object Info Message zu Start KP 4 â€“ Gibt es eine abschlieÃŸende Entscheidung zur\n\nEinfÃ¼hrung? Die Frage bezieht sich auf die finale Entscheidung fÃ¼r den Zielzustand.\n\nFÃ¼r den Migrationszeitraum ist keine Umsetzung der OIM geplant. Die OIM kommt nicht vor der\n\nvollstÃ¤ndigen EinfÃ¼hrung TTT.\n\n1.4 Gibt es schon eine Idee, wie die BKEID aussehen soll, wenn sie nicht CR ist? Die\n\nCase Reference ID sind fÃ¼r unterschiedliche GeschÃ¤ftsvorfÃ¤lle. Wichtig ist, dass diese ID\n\neineindeutig sein muss. Wissen wir wie das Core-Element also die BKE-Nr. aussieht?\n\nDie 24-stellige ID wird sich nur an den ersten beiden Stellen verÃ¤ndern. Die ersten beiden Stellen beschreiben den ObjektType. Dieser Ã¤ndert sich von â€žCRâ€œ zu â€žTCâ€œ. Der Core der BKE-ID\n\nergibt sich aus verschiedenen Parametern, die eine eindeutige ID ergeben.\n\n1.5 Heute werden Dauer-LÃœ manchmal in den Fplo angemerkt, wo / wie soll das in TTT\n\ngemacht werden?\n\nWir Ã¤ndern nichts am bisherigen Vorgehen. Die Dauer LÃ¼ ist erst in der BauFplo hinterlegt.\n\n1.6 Werden die DB InfraGO AG Ansprechpartner:innnen auch Ã¼ber die Schnittstelle geliefert?",275,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":5,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","311ec23abb1886fc1a745e7d042679288fd53bbb4846e2fcdffa7f6f6a344fe9"],["chunk_25ff8952542a96a12ad83474","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",7,"Seite 5","Die Kontaktinformationen werden auch Ã¼ber die Schnittstelle geliefert.\n\n1.7 Wo genau sehen wir bei GPE/FPE den/die Ansprechpartner:in fÃ¼r RÃ¼ckfragen bei der\n\nDB InfraGO AG. KÃ¶nnen wir das Testen?\n\nKontaktmÃ¶glichkeiten finden Sie unter dem Abschnitt Kontaktinformationen in den Fahrplanprodukten.\n\n1.8 Momentan kommunizieren wir intern und mit DB InfraGO zu Baustellen mit der ZvF- /\n\nFplo- Nummer. Diese hat 5 Stellen und eine logische numerische Ziffernfolge. Wie wird\n\ndie zukÃ¼nftige Kennzeichnung der BaumaÃŸnahmen erfolgen? Mit welchem Merkmal erkennt man, welches GPE zusammengehÃ¶rt? Eine einfache, maximal fÃ¼nfstellige Vorgangsnummer wÃ¤re auch weiterhin wÃ¼nschenswert. Die momentan verwendeten 8- stelligen alpha-numerischen BKE-Nummern erfÃ¼llen diese Voraussetzungen nicht.\n\nDie zugehÃ¶rigen BKE-Nummern werden an das jeweilige GPE verknÃ¼pft.\n\nBKE-Nummern entsprechen dem Format der TTT-Identifier und sind 24-stellig. Der Core des\n\nIndentifiers enthÃ¤lt die BKE-ID.\n\nV.IWF 41 Fragenkatalog 5",129,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":5,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","07490f64a65312ab299c4dca848b983c66adbad88ee3f7ed869c1f3f41609518"],["chunk_01505a4a3ee6005d8034d685","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",8,"Seite 6","1.9 Nach einen GPE soll die Beschreibung fÃ¼r die Stellungnahme nicht mehr notwendig\n\nsein, sondern das EVU soll ein alternativ Trassenvorschlag in Form einer gesamten\n\nTrasse bestellen. Verschlechterung und kann nicht hingenommen werden da diese ein\n\nerheblicher Mehraufwand nach sich zieht.\n\nDas Senden einer Gesamttrasse ist notwendig.\n\n1.10 Ist gewÃ¤hrleistet, dass bei einem Angebot einer Umleitungstrecke, die Streckenklasse im gesamten Laufweg angezeigt und ersichtlich ist?\n\nDie Streckenklasse wird ersichtlich sein.\n\n1.11 Der Prozessschritt â€žEntwurf Ausfall nach Stellungnahmeâ€œ sieht nicht vor, dass das\n\nEVU auf das ursprÃ¼ngliche GPE zurÃ¼ckfallen kann, wenn DB InfraGO den Ã„nderungsvorschlag des EVU nicht umsetzen kann. Diese Vorgehensweise kann nicht akzeptiert werden. Es wird jegliche Stellungnahme zum GPE verhindert, wenn das EVU dabei das Risiko eines Ausfalls der Trasse in Kauf nehmen muss.\n\nWenn DB InfraGO den Ã„nderungsvorschlag des EVU nicht umsetzen kann, entspricht das\n\nGPEnS/FPE inhaltlich dem GPE (sofern keine weiteren Anpassungen seitens InfraGO nÃ¶tig\n\nsind). Es liegt beim EVU zu entscheiden, ob die Trasse storniert werden soll. Das Diagramm ist\n\nan allen angemerkten Stellen korrekt, da es immer zu kurzfristigen StÃ¶rungen kommen kann.\n\nSelbstverstÃ¤ndlich erfolgt eine kurzfristige Ã„nderung nur wenn sie unvermeidbar ist.\n\n1.12 Wird in Anlage 10 das Freitextfeld fÃ¼r die Stellungnahme erwÃ¤hnt?\n\nLt. Anlage 10 (Fahrplan: EVU-Schnittstelle) gibt es ein Freitextfeld (FreeTextField) auf Message- und auf Location-Ebene. Das Freitextfeld darf nur Angaben enthalten, die nicht in einem\n\ndefinierten Attribut (Strukturelement) der Nachricht angegeben werden kÃ¶nnen.\n\n1.13 Warum wird ein GPE gesendet, obwohl kein Trassenvertrag vorliegt?",242,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":6,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","5713274a9306f3a49def10d5779cbaa15c854b9316139408dc92888750fc5336"],["chunk_d6166efb78728ed59ac0ebe8","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",9,"Seite 6","Mit der VerÃ¶ffentlichung des VorlÃ¤ufigen Netzfahrplans (VNP) kÃ¶nnen GPE versendet werden.\n\nDies gleicht dem heutigen Prozess, bei dem auf Basis des VNPs bereits ZvF gesendet werden\n\nkÃ¶nnen.\n\n1.14 Wann erfolgt die Anpassung zu den Zusatzleistungen, dass diese nicht mehr Ã¼ber\n\neinen Rabattcode gehen, sondern Ã¼ber baubedingte Zusatzleistungen und wo wird das\n\nstehen?\n\nIn der VerÃ¶ffentlichung im September in Anlage 1 bei â€žVerkehrsartKundeZusatzâ€œ wurde die AusprÃ¤gung â€žbaubedingteZusatzleistungâ€œ ergÃ¤nzt. Die Verwendung des Rabattcode fÃ¼r baubedingten Zusatzleistungen wurde verworfen.\n\n1.15 Was ist mit den verÃ¶ffentlichten BaumaÃŸnahmen bei Streckenpunkt.info. Was ist der\n\nsingle Point of Truth?\n\nDie Baustellendaten in strecken.info basieren auf der 12-Wochen-Bauvorschau. Nicht enthalten\n\nsind BaumaÃŸnahmen ohne betriebliche Auswirkung das sind z.B. BaumaÃŸnahmen in Streckendienstruhen, Langsamfahrstellen oder Sperrpausen. Die Baustellendaten dienen als zusÃ¤tzliche\n\nInformation.\n\n1.16 Was passiert mit den Ã„nderungen und entfernten BKE. Was ist mit dem Problem\n\nSplitt?\n\nEs soll zukÃ¼nftig eine Kreuzreferenz auf BKE-IDn mÃ¶glich sein. Die Umsetzung wird aktuell fÃ¼r\n\ndas Fahrplanjahr 2027 zu x-6,5 geplant. (Juni 2026)\n\n1.17 Wie werden die Ansprechpartner bei DB I fÃ¼r RÃ¼ckfragen definiert wenn der Grund\n\nfÃ¼r eine GPE nicht plausibel ist?\n\nKontaktmÃ¶glichkeiten finden Sie unter dem Abschnitt Kontaktinformationen in den Fahrplanprodukten.\n\nV.IWF 41 Fragenkatalog 6",193,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":6,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","d15797fd1269f07a5781f5ba25fcaf513c9f51f63526369a69ec3c71a81b86ac"],["chunk_856b440f917e19f3f339e730","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",10,"Seite 7","1.18 Wie ist der Prozess, wenn in eine Stellungnahme unterschiedliche Optionen beinhalten wÃ¼rde? Wir wÃ¼rden z.b. Variante A zurÃ¼ckmelden, sollte A nicht funktionieren aber\n\neine Variante B im Kopf haben. Es besteht die Sorge, dass wenn A nicht konstruiert werden kann \"irgendetwas\" konstruiert wird, obwohl wir als EVU bereits eine Alternative im\n\nHinterkopf haben.\n\nEine Alternative B kann z.B. Ã¼ber die Funktion \"Nachricht verfassen\" in der KOMBau hinterlegt\n\nwerden. Variante A wird Ã¼ber das Stellungnahmeformular eingegeben.\n\n1.19 In welchem Datenformat wird das GPE/FPE gesendet und wird es eine Beispiel\n\nGPE/FPE geben, damit wir prÃ¼fen kÃ¶nnen wie wir mit der neuen Datenstruktur umgehen\n\nkÃ¶nnen.\n\nWir verschicken die Planungsergbnisse im offiziellen Format der TAF/TAP-TSI-Schnittstelle\n\nÃ¼ber das vorhandene Common Interface. Siehe dazu die folgende Website Fahrplan: EVU-\n\nSchnittstelle Anlage 1 und Anlage 10.\n\n1.20 Wann wird der Bereich \"NetzausgelÃ¶ste Ã„nderungen (NAÃ„)\" in der PathOS Schulungsplattform mit Beispielen verfÃ¼gbar sein?\n\nInformationen finden Sie in folgendem Video: https://ecm-mediathek-cdn.deutschebahn.com/resources/video7/video_embed.html?url=/cdnenhancedecmvidhls/db292506/2801325/video_config.json&autostart=false&defaultquality=0&mute=false\n\nIm Handbuch pathOS pathOS - Handbuch V1.01 - Stand 03.2026 ab Folie 228 finden Sie Bilder\n\ndazu.\n\n1.21 Wie erfolgt die Ãœbermittlung des Zeitraumes, wenn durch eine zusÃ¤tzliche BaumaÃŸnahme die Verkehrstage innerhalb eines GPE geteilt werden? Erhalten wir fÃ¼r jede Nachricht einen GÃ¼ltigkeitszeitraum von 7 Tagen oder ist auch ein verkÃ¼rzter Zeitraum mÃ¶glich?\n\nDie Bautrasse des ursprÃ¼nglichen GPE wird im Folgeprodukt um die baubetroffenen Tage der",219,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":7,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","4b89853f59c058ba4aa04fcf1c430795d592e19891d8a8b321a6ed223ed63f96"],["chunk_17e5507361036c96859bc7a3","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",11,"Seite 7","neuen BKE eingekÃ¼rzt. FÃ¼r die baubetroffenen Tage der neuen BKE versenden wir ebenfalls\n\nein fristabhÃ¤ngiges Fahrplanprodukt.\n\nV.IWF 41 Fragenkatalog 7",20,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":7,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","0bb8e58be5a626000eecea233c3d3de758deba818eb752669456eab096aae103"],["chunk_53f2938531af87c7f1605075","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",12,"Seite 8","Neue Fahrplanprodukte\n\n1.1 Kann in der Stellungnahme zum GPE eine Arbeitsgruppe zu einem BKE gefordert\n\nwerden?\n\nAbschnitt 3 Abs 2 der Ril 402.0305 sagt u.A: \"ZusÃ¤tzlich zu den in dieser Richtlinie beschriebenen Konsultationsprozessen besteht die MÃ¶glichkeit, sich bei Fragen und Hinweisen direkt an\n\nihre Ansprechpartner innerhalb der DB InfraGO AG zu wenden.\"\n\n1.2 Wie ist gewÃ¤hrleistet, dass zu Beginn der Fahrplanjahres trotz doppelter GPE-Menge\n\ndie QualitÃ¤t und Fristigkeit gut ist?\n\nDurch den Verschub der GPE-Frist (z-15), unsere interne Arbeitssteuerung und den sukzessiven Hochlauf der IT streben wir eine fristgerechte Bearbeitung an.\n\n1.3 Wie erkennt man BKEn in GPE, die nicht in KP 3 waren? Wie wird die Information\n\n(Dauer, Abschnitt, Regelungsart etc.) den EVU bereitgestellt? Wie kÃ¶nnen Konzepte zu\n\nden BKEn/ZÃ¼gen abgestimmt werden? Es ist eine ErklÃ¤rung notwendig.\n\nIm GPE sind die auslÃ¶senden BKE-IDn sichtbar. DarÃ¼ber kann in der KOMBau eine entsprechende BKE eingesehen werden. Dauer, Abschnitt und Art der EinschrÃ¤nkung werden hier angezeigt. UnterjÃ¤hrig ausgeregelte ZÃ¼ge werden Ã¼bers GPE konsultiert. BKEn > 1 werden in den\n\nKP 1-3 abgestimmt. Sollte es Ã„nderungen dazu geben, dann werden die BKE in der KOMBau\n\nneu konsultiert. Bei Fahrplanprodukten ohne eine zugehÃ¶rige BKE-ID, erkennt man den Baubezug am versendeten FPE.\n\n1.4 Wie wird fÃ¼r eine NAÃ„ mit einer GÃ¼ltigkeit ab einem Donnerstag, welche an einem\n\nMontag zugestellt wird, die Verfristung ermittelt? Erfolgt die Berechnung basierend auf\n\ndem mitgesendeten GÃ¼ltigkeitsbeginn oder auf Basis des 1. Verkehrstages.\n\nBerechnung erfolgt auf Basis des 1. Verkehrstages.\n\n1.5 Gilt eine NAÃ„ > 3 Tage ohne Reaktion als angenommen?",250,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":8,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","be85a9cd94d978721a71243098bebd74162c24424eb6e5bb01964ab7edcf2a14"],["chunk_bee262f023fcd0b360bc300a","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",13,"Seite 8","Eine NAÃ„ gilt nach Versand direkt als angenommen. FÃ¼r ZB besteht jedoch die MÃ¶glichkeit, die\n\nTrasse innerhalb von drei Arbeitstagen (Montag bis Freitag, ausgenommen bundeseinheitliche\n\nFeiertage) kostenfrei zu stornieren.\n\nSiehe dazu INB (2027) Ril. 402.305 Abschnitt 8 Absatz (6) â€“ (...) ZB haben die MÃ¶glichkeit, innerhalb von drei Arbeitstagen, die angepassten Trassen kostenfrei zu stornieren.\n\n1.6 NAÃ„ werden tagesscharf verschickt, wie ist das gemeint? Wird es hier eine wochenweise BÃ¼ndelung geben? Wir erwarten, dass alle NAÃ„ wg. Bau bis z-8 vorliegen.\n\nTagesscharfer Versand bedeutet in diesem Zusammenhang, dass FPEs nicht montags gesammelt versendet werden, sondern direkt, wenn das FPE und NAÃ„ fertiggestellt sind.\n\n1.7 Ist die NAÃ„ als Resultat des Bauprozesses vollstÃ¤ndig im EBuLa Fahrplan abgebildet? Sind damit die zusÃ¤tzlichen Fplo Ìen obsolet?\n\nDie NAÃ„ ist ein â€žkaufmÃ¤nnischesâ€œ Produkt. Dort werden nicht ausreichend Attribute zur Durchfahrt enthalten sein. Das Fahrplanprodukt \"BauFplo\" ist auch im Annex Prozess die offizielle\n\nBauFahrplananordnung und wird weiter existieren und relevant fÃ¼r die DurchfÃ¼hrung der Zugfahrt sein. Dort werden die entsprechenden relevanten Daten zur VerfÃ¼gung gestellt, die FDL\n\nund TF benÃ¶tigen. Mit BSV (Baufahrplan Service VerÃ¶ffentlichung) liefern wir die Daten in einer\n\nneuen Form trassenbezogen sowohl als pdf als auch Ã¼ber eine neue Kunden-Schnittstelle.\n\nV.IWF 41 Fragenkatalog 8",202,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":8,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","f578f1d624812bc9337999eb625c89ed4c9a85abcf4a6ffc8cc064df2d7395c4"],["chunk_75435e7ced3174d3c29c5b66","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",14,"Seite 9","1.8 GrundsÃ¤tzlich ist die Erwartungshaltung weiterhin, dass es keine Inkonsistenzen bei\n\nGPE, FPE und NAÃ„ gibt. FÃ¼r einen Ãœbergangszeitraum, jetzt nur Fplj 2027 sind Mindestanforderungen zu diesem Thema zu erfÃ¼llen.\n\nRÃ¤umliche Inkonsistenzen werden mit der EinfÃ¼hrung von TTT durch den verÃ¤nderten Arbeitsprozess ab FPE ausgeschlossen. RÃ¤umliche Inkonsistenzen in GPE und GPE nach SN kÃ¶nnen\n\nnicht komplett ausgeschlossen werden. BezÃ¼glich der zeitlichen Inkonsistenzen werden, wie\n\nbereits kommuniziert, die aktuellen Niveaus gehalten. Eine Reduzierung der zeitlichen Inkonsistenzen ist mit fortschreitender Automatisierung sowie der Umsetzung des Annex VII zu erwarten. Inkonsistenzen werden im GPE/GPE nach SN, FPE und NAÃ„ dargestellt. Es kann aktuell\n\njedoch nicht sichergestellt werden, dass dies zum Beginn des Versands der Fahrplanprodukte\n\numgesetzt ist. Auch auf eine inkonsistente GPE-Trasse kann mit einer Stellungnahme reagiert\n\nwerden.\n\n1.9 Wie ist der aktuelle Stand zur Stafette? Es besteht der Wunsch nach regelmÃ¤ÃŸigen\n\nUpdates dazu.\n\nDie Stafette befindet sich im Fpl. Jahr 2026 weiterhin im Pilotverfahren mit 31 Korridoren. Mit\n\nEinfÃ¼hrung von TTT soll sie wie vorgestellt im neuen GPE/FPE Prozess aufgehen.\n\n1.10 Wie erfolgt der Hinweis auf Reisendensicherung in GPE/NAÃ„? KÃ¶nnen wir davon\n\nausgehen, dass es wie im Jahresfahrplan gehandhabt wird -> Nutzung Feld fÃ¼r â€žBahnsteiglÃ¤nge nicht ausreichendâ€œ und eine Information Ã¼ber das Gleis?\n\nDer Hinweis der geringen NutzlÃ¤nge wird erfolgen. Eine konkrete Angabe der Differenz als Meterangabe erfolgt nicht, da dafÃ¼r kein TAF/TAP-TSI Feld vorgesehen ist.\n\n(INB 2027) Ril 402.0305 Abschnitt 8 Absatz (9)\n\nWird bei der Konstruktion festgestellt, dass fÃ¼r verÃ¶ffentlichte Regel- und/oder Bedarfshalte",243,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":9,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","c46e99e7f31f5ca4c5b4c26b8a82e8b7427b97d591a28b0dae3c57dd6483c3bf"],["chunk_63be991d44e70486a6be4150","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",15,"Seite 9","nicht alle nach der Trassenanmeldung mit Reisenden besetzten Wagen an den Bahnsteig gelangen kÃ¶nnen, muss fÃ¼r die betroffene Stelle im Feinplanungsergebnis (FPE) darauf hingewiesen werden.\n\nDie DB InfraGO AG ergÃ¤nzt im NAÃ„ an der entsprechen-den Betriebsstelle â€žBahnsteignutzlÃ¤nge nicht ausreichendâ€œ sowie die sich aus der Konstruktion ergebende Gleisnummer. Das EVU\n\nist danach zu entsprechenden SicherungsmaÃŸnahmen gemÃ¤ÃŸ EBO verpflichtet. Zu beachten\n\nist, dass es sich bei dieser Angabe der Gleisnummer um einen Planungsstand handelt und sich\n\ndie Gleisnummer im Nachgang Ã¤ndern kann.\n\n1.11 Absage einer BM: Wenn eine BM ausfÃ¤llt, zu der uns bereits ein GPE zugespielt\n\nwurde, bekommen wir dazu eine Info per Mail? Bereits gestellte Frage von August 2024:\n\nWenn ein Zug im Nachgang einer GPE doch keine Ã„nderung durch Bau mehr erfÃ¤hrt und\n\ndamit keine NAÃ„ mehr notwendig ist, wird trotzdem eine FPE versendet?\n\nIst ein Zug nicht mehr baubetroffen, wird die letzte Bautrasse erneut als PDM (PathDetailMessage) mit TOI (Type of information) â€šwithdrawalâ€˜ gesendet. Siehe dazu Anlage 10 (Fahrplan:\n\nEVU-Schnittstelle)\n\n1.12 Absage einer BM bei Mehrfachbetroffenheit: Beispiel = GPE mit 3 Baustellen, eine\n\nim SÃ¼den, eine im Norden und eine im Osten, alles konsistent und eine der Baustellen\n\nfÃ¤llt aus - bekommen wir ein neues GPE?\n\nEine Aktualisierung der Bautrasse erfolgt im Folgeprodukt (GPEnS oder FPE).\n\n1.13 Kann die RÃ¼ckmeldung auf das GPE auch Ã¼ber die Trassenschnittstelle erfolgen?\n\nSprich, wir importieren das GPE als Trassen in unsere Systeme und senden Ihnen die\n\nRÃ¼ckmeldung auf gleichem Wege zurÃ¼ck? Oder muss die RÃ¼ckmeldung via KOMBau erfolgen?\n\nDie Stellungnahme auf das GPE kann Ã¼ber die KOMBau oder die TAF/TAP-konforme EVU-",259,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":9,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","f2010fb90e86050358df2cc8f2c45ca65c3b3365e051573f4ab688680354ed8d"],["chunk_14f65f56b5932dd10be09e55","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",16,"Seite 9","Schnittstelleerfolgen. HierÃ¼ber kÃ¶nnen GPE, GPEnS und FPE auch empfangen und im eigenen\n\nSystem weiterverarbeitet werden.\n\nV.IWF 41 Fragenkatalog 9",19,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":9,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","b5c55ebd07b1c5774e82f42ab56d0285b4e1512ece9d418411137a8ab4019b9a"],["chunk_402bef0c890cb1ddcdb137b6","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",17,"Seite 10","1.14 FÃ¼r den Fall, dass eine grÃ¶ÃŸere BKE nach dem GPE-Prozess notwendig wird die erst\n\nmit FPE kommuniziert wird, bitten wir unbedingt um Kontaktaufnahme und Konzeptabstimmung auf Linienebene (ohne zunÃ¤chst einzelne Trassen zu betrachten)\n\nWenn dieser Fall eintreten sollte, wird es nicht mÃ¶glich sein einzelne EVU zu Abstimmungen zu\n\nkontaktieren. KÃ¶nnen bestehende Fristen nicht eingehalten werden, konsultiert die DB InfraGO\n\nAG die ZB und EIU umgehend. Siehe dazu (INB 2027) Ril 402.0305 Abschnitt 9.\n\n1.15 Wird vor der Absage von Baustellen mit den EVU gesprochen, ob die Absage zur erneuten Umplanung bzw. RÃ¼ckfallen auf Vertragszustand fÃ¼hrt oder ob man den ausgeplanten Bauzustand wegen ggf. zu kurzem Vorlauf erhÃ¤lt?\n\nEs erfolgt keine gesonderte Abstimmung. Vor Versand des GPE zu z-24 erfolgt die Absage der\n\nBaumaÃŸnahme und die Regeltrasse erhÃ¤lt ihre GÃ¼ltigkeit zurÃ¼ck. Nach z-24 erfolgt die PrÃ¼fung\n\nder KomplexitÃ¤t der Dekonstruktion. Nach z-8 erfolgt keine Ã„nderung der Bautrasse mehr, die\n\nFPE-Trasse bleibt bestehen, da die Bautrasse bereits zur Regeltrasse geworden ist.\n\n1.16 GPE nach Stellungnahme/ Zielzustand: Es werden aktuell einige Prozesse auf das\n\nGPE nach Stellungnahme (GPEnS) aufgesetzt z.B.\n\n-kurzfristige BaumaÃŸnahmen, die nicht konsultiert werden mÃ¼ssen\n\n-und Splittung der Path bei OTN-Wechsel\n\nWo werden diese Dinge im Zielzustand ohne GPE nach Stellungnahme aufgesetzt? Ist\n\nder Auftragstyp nicht mehr nur temporÃ¤r vorgesehen oder wird dann davon abgewichen,\n\ndass FPE identisch zur NAÃ„ ist?\n\nIm Zielzustand passiert das im FPE.\n\n1.17 Sind BKE gleisscharf beschrieben? Unterschiede BKE 1 zu den anderen BKE-Kategorien?\n\nBKE sind nicht gleisscharf beschrieben. Der Unterschied ist, dass unterjÃ¤hrig die Konsultation",251,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":10,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","574608e06c4913a9c31b005d84e4bb1da2bd52ad96fa1ef290c509334f531ec5"],["chunk_3d13c5c80373fc74be06ba30","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",18,"Seite 10","mittels des GPE stattfindet und die BKE jeweils dazu verlinkt ist. Siehe dazu auch (INB 2027)\n\nRil. 402.0305 Abschnitt 1 Absatz 11.\n\n1.18 Zu Absage einer BaumaÃŸnahme -> Szenario: Der Ersatzverkehr lÃ¤sst sich nicht mehr\n\nzurÃ¼ckdrehen, Vorschlag Kunden/EVU -> hier wÃ¤re doch eine Einzelfallbetrachtung besser!\n\nEs gilt die Stichtagsregelungen. Einzelfallbetrachtungen kÃ¶nnen diskriminierend sein, daher gilt\n\ndie Regelung fÃ¼r alle, um Transparenz herzustellen.\n\n1.19 Welchen GÃ¼ltigkeitszeitraum kann eine FPE/NAÃ„ umfassen? Immer nur maximal den\n\nZeitraum des vorgelagerten GPE/GPE nach Stellungnahme? Kann der GÃ¼ltigkeitseitraum\n\nder FPE/NAÃ„ auch lÃ¤nger als 7 Tage sein, wenn es kein GPE gab?\n\nEin FPE/ eine NAÃ„ umfasst maximal den Zeitraum des GPE/ GPEnS. In AusnahmefÃ¤llen kann\n\neine NAÃ„ 8 Tage umfassen.\n\n1.20 Nicht alle Trassen einer BKE erhalten zwingend ein GPE. In einer BKE ist nach unserem Kenntnisstand enthalten, welche Trassen dann genau ein GPE erhalten werden. Das\n\nErkennen betrachten wir als sehr aufwendig.\n\nAn einer BKE sind nicht alle betroffenen ZÃ¼ge erkenntlich, sondern nur die Obermenge aller potenziell betroffenen ZÃ¼ge.\n\nV.IWF 41 Fragenkatalog 10",168,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":10,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","60be98a49d82d6b50db83fcdc0e617536126fe1c429b1a8b8150f68caa87cda9"],["chunk_c9e99ffa32775abb66918fb2","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",19,"Seite 11","1.21 Erfolgt auch in diesen AusnahmefÃ¤llen die Kommunikation immer Ã¼ber mindestens\n\nNAÃ„ oder gibt es auch andere Kommunikationsformate?\n\nWir senden immer ein NAÃ„, auch in AusnahmefÃ¤llen nach Ril 402.0305 Abschnitt 9 (INB 2027).\n\n1.22 Kann wÃ¤hrend eines Stellungnahmeverfahren NAÃ„ (3 WT) eine weiteres NAÃ„ wegen\n\neiner MaÃŸnahme â€žNr.14â€œ folgen?\n\nEs erfolgt eine Ã„nderung der INB 2027 Ril. 402.305 Abs. 8 (6). Es gibt keinen Ablehnen Button,\n\nsondern die Stornierung erfolgt im Regelprozess.\n\nEine NAÃ„ gilt als neuer Vertragszustand. Die neue Vertragstrasse kann innerhalb von 3 Arbeitstagen kostenfrei storniert werden. Dadurch besteht die beschriebene Problemstellung nicht.\n\n1.23 Erstversendung der GPEs: In den INB 2027 sowie im TTT-Dialog vom 30.10.2025\n\nwerden unterschiedliche Termine fÃ¼r die Erstversendung der GPEs genannt. Bitte teilen\n\nSie uns das konkrete, verbindliche Datum der Erstversendung mit.\n\nDie korrekten Daten sind auf der Website der DB InfraGO im Terminkalender fÃ¼r das Kalenderjahr 2026 ersichtlich. Die Kund:inneninformation dazu wurde am 13.11.2025 versendet.\n\nLink Website: https://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34-eu-11857512\n\n1.24 Werden bei der 3-wÃ¶chigen Stellungnahmefrist bundeseinheitliche Feiertage berÃ¼cksichtigt?\n\nBei der 3-Wochenfrist fÃ¼r die Stellungnahmen auf ein GPE werden keine Feiertage berÃ¼cksichtigt. Diese 3-wÃ¶chige Stellungnahmefrist kann nicht verkÃ¼rzt werden. Bei Fristangaben in Form\n\nvon Arbeitstagen (Montag bis Freitag) werden bundeseinheitliche Feiertage nicht in die Frist gerechnet.",201,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":11,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","b66a2911c9b0cbdb68050c103fae62efddf54e057fb6c40f2d28b114e5bf7459"]]');
