INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_7611e2a70853cde30fa75924","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",20,"Seite 11","1.25 In der ZvF ist heute erkennbar welcher Streckenabschnitt in welchem Zeitraum gesperrt oder nur im GWB befahren werden kann. Mitunter sind noch weitere Informationen, wie einzurichtende La-Stellen oder die Sperrung von Gleisen in den KnotenbahnhÃ¶fen erkennbar. Diese Informationen sind fÃ¼r uns als Nahverkehrs-EVU notwendig, um alle\n\nAuswirkungen auf den Zugbetrieb beurteilen zu kÃ¶nnen und eine entsprechende Stellungnahme abzugeben. Im neuen Prozess wird die ZvF durch das GPE ersetzt. Dieses ist\n\njedoch zugbezogen. Die o.g. Informationen aus der ZvF hinsichtlich des Sperrabschnittes und der zeitlichen Dauer fehlen hingegen. Hier ist lediglich ein Verweis auf die in der\n\nKOMBau kommunizierten BKE enthalten. FÃ¼r Bauarbeiten in 2026 war der letzte Konsultationszeitpunkt in der KOMBau zu x-4. Die fÃ¼r Januar 2026 enthaltenen BKE stimmen in\n\nweiten Teilen nicht mit den Informationen der versendeten ZvF Ã¼berein. Einzelne BKE\n\nwurden nicht durch eine ZvF prÃ¤zisiert, weshalb wir davon ausgehen, dass diese entfallen sind. In anderen FÃ¤llen gibt es eine ZvF, obwohl in der BKE steht, dass unsere ZÃ¼ge\n\nnicht betroffen sind oder es gibt eine ZvF, ohne dass eine dazu passende BKE in der\n\nKOMBau existiert.\n\nWir haben deshalb an den Support der KOMBau folgende Fragen gestellt und wÃ¼rden\n\ndiese auch gerne morgen diskutieren: 1. Werden die BKE weiterhin (nach dem Zeitpunkt\n\nx-4) aktualisiert (Ausfall, Verschiebung oder Ã„nderung der Betroffenheit) und wenn ja zu\n\nwelchen Zeitpunkten? 2. Werden neu eingerichtete Baustellen auch mit einer BKE in die\n\nKOMBau aufgenommen? Wo sind diese zu finden?\n\nMit x-4 werden RÃ¼ckmeldungen der DB InfraGO AG zu Stellungnahmen der BKE des Teil 2, sowie der GesamtÃ¼berblick/Planungsstand zu allen BKE verÃ¶ffentlicht. Deshalb ist es mÃ¶glich,",265,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":11,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","fac57f583f03e9e2b906982372bc49b95f25a68085729c40ebf7a6cfdae21ecc"],["chunk_d1dbaa23a5fa3af905cb684f","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",21,"Seite 11","dass x-4 nicht alles aus x-8,75 beinhaltet.\n\nV.IWF 41 Fragenkatalog 11",11,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":11,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","3d3181dbbbaea3fdb39226b9ac786f9f06554d70e9e9c3bee1fe94abaa38634d"],["chunk_b4562b3862e171c186eab1d7","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",22,"Seite 12","1.26 Ist eine Teilstornierung im Regelprozess mÃ¶glich bei 3-tÃ¤giger Frist auf NAÃ„?\n\nDie kostenfreie Stornierung innerhalb von drei Arbeitstagen gilt nur fÃ¼r die komplette Stornierung der Trasse der NAÃ„-Trasse. Eine kostenfreie Teilstornierung ist hier nicht mÃ¶glich.\n\n1.27 Gibt es feste ZeitrÃ¤ume fÃ¼r den NAÃ„-Versand?\n\nDie NAÃ„ wird zeitlich mit dem FPE versendet. Dies ist im Regelprozess bis spÃ¤testens z-8 (z-5\n\nbei SGV) zu erfolgen. Ein Versand zu einem frÃ¼heren Zeitpunkt ist mÃ¶glich.\n\n1.28 Ein mÃ¶glicher GPE-Versand kann bereits ab dem 06.07.26 erfolgen. Es stellt sich die\n\nFrage, wie sich die Trasse im ENP darstellt, falls eine GPE abgegeben wird â€“ sei es mit\n\nStellungnahme oder Annahme. Wird die ENP-Trasse durch die Ã„nderung der Stellungnahme bzw. Annahme berÃ¼cksichtigt, oder bleibt die ENP-Trasse die Trasse zur ursprÃ¼nglichen Bestellung? Danke vorab fÃ¼r die AufklÃ¤rung im Ãœbrigen plÃ¤dieren wir fÃ¼r\n\neine Erstversendung auf Basis ENP.\n\nIm ENP wird unterjÃ¤hriger Bau nicht berÃ¼cksichtigt. Die Bautrasse wird Ã¼ber FPE/ NAÃ„ kommuniziert.\n\n1.29 Wird auch bei NEP I und NEP II und den verkÃ¼rzten Fristen ein GPEnS versendet?\n\nEs wird kein GPEnS zu den verkÃ¼rzten GPE Fristen (NEP I und NEP II) versendet, erst wieder\n\nwenn die regulÃ¤re Frist des GPE zu z-24 erreicht wird.\n\n1.30 Wird es einen Zeitplan fÃ¼r den Hochlauf der GPE geben?\n\nWir kÃ¶nnen keinen Hochlaufplan zur VerfÃ¼gung stellen.\n\n1.31 Wann wird die Zugbetroffenheit konkretisiert? Ab welchem Zeitpunkt werden konkrete Zugnummern fÃ¼r BaumaÃŸnahmen der Konsultationsphasen verÃ¶ffentlicht? Bisher\n\nInfo von Trassenkonstrukteur an EVU. Wie ist der Zielprozess?",243,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":12,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","647db5144ccfd428c38c00f586e54895fedd084d54d5be1d0c88fc11b1abf1e7"],["chunk_fe4144e76e5432ecd38a3dad","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",23,"Seite 12","Erster mÃ¶glicher Versand des ersten GPE und Beginn Stellungnahmen in KOMBau, somit konsultierte Trassen sind ab 06.07.2026 mÃ¶glich. Ein direkter Bezug zwischen Zugbetroffenheit\n\nund BaumaÃŸnahme ist erst im GPE erkennbar.\n\n1.32 ZÃ¤hlt die Stornierung der neuen Regeltrasse, die vorher eine Bautrasse war, in die\n\nStornoquote?\n\nBautrassen, die innerhalb von drei Tagen storniert werden, zÃ¤hlen nicht in die Stornoquote.\n\n1.33 Auf geplanter Infrastruktur ist eine BaumaÃŸnahme geplant, deswegen wird gezielt\n\neine Dritt Infrastruktur genutzt. Hier ist bei der Erstellung eines Testfall aufgefallen, das\n\nin RB West prozessual anders verfahren wird wie in RB SÃ¼d. Wir bitten um Bekanntgabe\n\neiner einheitlichen prozessualen Regelung.\n\nDas Vorgehen wird individuell von den jeweiligen Regionen bearbeitet und weicht ggf. von anderen Regionen ab wegen unterschiedlicher Ã¶rtlicher Gegebenheiten oder Abstimmungsvorgehen mit Fremd-EIU.\n\n1.34 Gibt es die GPE z-15 nur im ersten Jahr der EinfÃ¼hrung TTT (also fÃ¼r den Fpl 2027)\n\noder ggf. alle Jahre wieder (ist bei InfraGO noch in KlÃ¤rung): Dann werde uns ansonsten\n\njedes Jahr GPEn immer 9 Wochen zu z- 24 zu spÃ¤t Ã¼bergeben.\n\nHier geht es um das Fahrplanjahr 2028, die Fristen werden derzeit noch abgestimmt.\n\n1.35 Bleibt VNP/ENP-Frist gleich und ist vorgehen mit erstem GPE zu z-15 auch fÃ¼r Folgejahre geplant?\n\nHier geht es um das Fahrplanjahr 2028, die Fristen werden derzeit noch abgestimmt.\n\nV.IWF 41 Fragenkatalog 12",216,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":12,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","86ac2bb93d487ab211a1ff9567511ecbd7a3c2b0e8ffdbe8e869bc3a8d5d9eaa"],["chunk_b9771393e13a5afdcb63d73e","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",24,"Seite 13","1.36 Ab welchem Zeitpunkt kann damit gerechnet werden, dass der ENP die Datengrundlage der GPEs ist?\n\nHier geht es um das Fahrplanjahr 2028, die Fristen werden derzeit noch abgestimmt.\n\n1.37 Muss das Zugnummernkontingent fÃ¼r jedes GPE eine Zugnummer eingegeben werden oder geht hier eine Linienbearbeitung? Oder erhalten TaktzÃ¼ge von DB InfraGO eine\n\nZugnummer?\n\nEine Linienbearbeitung geht aktuell nicht. Die Baufahrplankonstrukteur:innen kÃ¶nnen nicht sicherstellen, dass sich die Information aus einer Stellungnahme gemerkt wird und fÃ¼r z.B. 100\n\nandere ZÃ¼ge genutzt wird.\n\n1.38 Folgendes Beispiel einer Mehrfachbetroffenheit am linken Rhein. Die Herausforderung, die Thematik im GPE erkennen zu kÃ¶nnen. Es gibt die BefÃ¼rchtung, dass dort ggf.\n\nAusfall Mainz - KÃ¶ln drinsteht, da unklar, ob diese KomplexitÃ¤t im GPE abbildbar; Informationen sind aktuell in den ZvF''en nur mit sehr hohem Aufwand seitens der Bearbeiter\n\nBaufahrplÃ¤ne mÃ¶glich.\n\nMehrfachbetroffenheiten je Zugfahrt werden in den neuen Fahrplanprodukten verarbeitet und\n\nmittels der zugehÃ¶rigen BKE-IDn angezeigt.\n\n1.39 Wo findet man in den INB die Annahme und Ablehnung vom GPEnS und warum ist\n\ndas eine Frist von 1 Woche?\n\nWir planen eine PrÃ¤zisierung der INB 2027 um die Frist einer Woche fÃ¼r Annahme und Ablehnung zu ergÃ¤nzen.\n\n1.40 Wann ist der Versand der letzten ZvF Dokumente bei A und B MaÃŸnahmen geplant?\n\nâ€žDer letzte Tag im Fahrplanjahr 2026 ist Samstag, der 12.12.2026. Von diesem Tag 15 Wochen\n\nbei A-MaÃŸnahmen und 10 Wochen bei B-MaÃŸnahmen zurÃ¼ckgerechnet, ist die Versendung der\n\nletzten ZvF-EndstÃ¼cke ausgehend von dieser Frist bis 24.08.2026 fÃ¼r A-MaÃŸnahmen und bis",242,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":13,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","eb94b74ce4fb25a3196f091e6b724b2aa4c8e5562a6398dad538754ac3d477dd"],["chunk_138691c332e241118ad6bb32","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",25,"Seite 13","28.09.2026 fÃ¼r ZvF-Dokumente bei B-MaÃŸnahmen vorgesehen. Allerdings ist nicht ausgeschlossen, dass auch nach dem 24.08.2026 bzw. 28.09.2026 ZvF-Dokumente fÃ¼r A- und B-\n\nBaumaÃŸnahmen versendet werden.\n\n1.41 Was ist der spÃ¤teste Zeitpunkt, zu dem eine Bestellung einer neuen Trasse im GelV\n\n(Gelegenheitsverkehr) in diesen FÃ¤llen mÃ¶glich ist?\n\nDie Anmeldung zum unterjÃ¤hrigen Gelegenheitsverkehr sind jederzeit mÃ¶glich.\n\n1.42 Ist die Anmeldung einer neuen Trasse im GelV direkt nach Ablehnung mÃ¶glich oder\n\nerst ab z-8 vor der relevanten BaumaÃŸnahme?\n\nSofern noch keine Bearbeitung der kundenausgelÃ¶sten Stornierung erfolgt ist, ist die Trasse\n\nnoch aktiv und wird als belegte KapazitÃ¤t in den Systemen angezeigt. Die KapazitÃ¤t kann und\n\ndarf dann nicht nochmals belegt werden. Dies kann erst nach der Bearbeitung der Stornierung\n\nerfolgen.\n\n1.43 Wenn man ein GPE, GPEnS oder FPE ablehnt, erfolgt die netzseitige Stornierung der\n\nTrasse. AnschlieÃŸend kann man im Rahmen des GelV eine neue Trasse bestellen.\n\nNach Ablehnung des GPE oder GPEnS erfolgt die Stornierung der Bau- und Regeltrasse. Ein\n\nFPE ist immer automatisch zugestimmt und kann innerhalb von 3 Tagen kostenfrei storniert\n\nwerden. Das Neubestellen, bleibt der bisherige Regelprozess im Gelegenheitsverkehr. Siehe\n\ndazu die Ril 402.0204.\n\n1.44 Wenn im Bauprozess ein GPE abgelehnt oder eine NAÃ„ storniert wird: Kann unmittelbar danach erneut eine Trasse mit derselben OTN bestellt werden?\n\nEs kann noch nicht unmittelbar danach erneut die Trasse mit der OTN bestellt werden, da diese\n\neinen internen Bearbeitungsprozess durchlÃ¤uft. Wenn die Stornierung bearbeitet wurde, wird\n\ndie Zugnummer wieder systemseitig fÃ¼r eine Neubestellung freigegeben.\n\nV.IWF 41 Fragenkatalog 13",245,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":13,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","c63e381e7f66d3cf3a605330fb26be9bff208df64c7ee907d7a7857c4b7b6539"],["chunk_429b11ccf655a5da4ce53b29","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",26,"Seite 14","1.45 Wie oft kommt es vor, dass FPE ohne GPE verschickt wird oder es keine BKE-ID\n\ngibt?\n\nEine konkrete Anzahl lÃ¤sst sich leider nicht angeben, da die FÃ¤lle nicht prognostizierbar sind.\n\n1.46 Werden Havarie NAÃ„s dann auch automatisch zum Vertag?\n\nEin FPE bzw. eine netzausgelÃ¶ste Ã„nderung bei Havarien stellt automatisch einen neuen Vertrag dar, auch wenn es hierzu kein GPE oder GPEnS gibt.\n\n1.47 Zu VerÃ¶ffentlichungsterminen der Fahrplanprodukte (GPE, GPEnS, FPE/ NAÃ„, etc.).\n\nSind diese Termine starr oder kann das GPE auch schon zu einem frÃ¼heren Zeitpunkt\n\nverÃ¶ffentlicht werden?\n\nIm Regelprozess sind die Fristen starr. Das GPE wird immer montags zu z-24 verÃ¶ffentlicht.\n\nEine frÃ¼here VerÃ¶ffentlichung des GPEs wird nicht erfolgen.\n\n1.48 Erfolgt der GPE-Versand auch montags um 06:00 Uhr, wenn der Montag ein Feiertag\n\nist oder wann erfolgt der Versand dann?\n\nDer Versand erfolgt immer montags, unabhÃ¤ngig von Feiertagen.\n\n1.49 Gelten die starren Fristen auch fÃ¼r NAÃ„/FPE?\n\nTagesscharfer Versand bedeutet in diesem Zusammenhang, dass FPE nicht montags gesammelt versendet werden, sondern direkt, wenn das FPE und NAÃ„ fertiggestellt sind.\n\n1.50 Und was passiert, wenn das GPE mit z-24 verÃ¶ffentlicht ist und sich dann nochmal\n\netwas an den Trassen verÃ¤ndert? Z.B. Ausfall einer Baustelle? Ich hoffe nicht, dass dann\n\ndie nÃ¤chste Info erst mit FPE erfolgt\n\nEine Aktualisierung der Bautrasse erfolgt im Folgeprodukt (GPEnS oder FPE).\n\n1.51 Wie ist das Vorgehen, wenn nach Versand der GPE eine weitere (neue) BaumaÃŸnahme den Zuglauf beeintrÃ¤chtigt?\n\nEine Aktualisierung der Bautrasse erfolgt im Folgeprodukt (GPEnS oder FPE).\n\n1.52 Die 3 Tagefirst in der Frage \"ZÃ¤hlt die Stornierung der neuen Regeltrasse, die vorher\n\neine Bautrasse war, in die Stornoquote?\" sind das Werktage oder Kalendertage?",269,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":14,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","613fea635a872d3f6f4f740f7c8f813520bb13443c62142510ffcffe23cdfd26"],["chunk_03151149222acde0968f9467","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",27,"Seite 14","Die Fristangaben erfolgen in Form von Arbeitstagen (Montag bis Freitag), dabei werden bundeseinheitliche Feiertage nicht in die Frist gerechnet.\n\n1.53 Im Falle, dass eine BaumaÃŸnahme nach Versand der BauFplo entfÃ¤llt, ist es mÃ¶glich\n\ndiese zu stornieren/zurÃ¼ckzuziehen und Neue Trassen unter Neuen Zugnummern zu bestellen. Dies wÃ¤re insbesondere bei groÃŸen TeilausfÃ¤llen relevant.\n\nAb z-8 Wochen sind Ã„nderungen an der Bautrasse nicht mehr mÃ¶glich. Die FPE-Trasse bleibt\n\nbestehen, da die Bautrasse bereits als Regeltrasse gefÃ¼hrt wird.\n\n1.54 Prozesstreu ( Versand zu Z - 24 ) ist gewÃ¤hrleistet? Oder wird es weiterhin verspÃ¤tete Lieferungen von Seiten DB InfraGO AG geben?\n\nEs kann nach Ril. 402.0305 (INB 2027) Abschnitt 9 zu Ausnahmen bei der Anwendung von\n\nFristen zur Konsultation, Abstimmung und Koordinierung von BKE sowie Ãœbergabe von\n\nGPE/FPE kommen.\n\n1.55 Erfolgt der GPE-Versand auch montags um 06:00 Uhr, wenn der Montag ein Feiertag\n\nist oder wann erfolgt der Versand dann?\n\nGPE und GPEnS Versand ist immer montags starr, unabhÃ¤ngig ob ein Feiertag ist.\n\nV.IWF 41 Fragenkatalog 14",163,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":14,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","588764142dd83a948ab6c92c02afc9f0087427668d642cd37b0c7dd6c424173d"],["chunk_0b62c39716a03e9cd74deaf4","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",28,"Seite 15","1.56 KÃ¶nnen Sie ebenfalls bestÃ¤tigen, dass die VerÃ¶ffentlichung von GPEnS immer zu z-\n\n15 und FPE immer zu z-8 und nicht frÃ¼her erfolgt?\n\nDas GPEnS wird, wie auch das GPE immer gesammelt und montags versendet.\n\n1.57 Muss somit nun jeden Montag einen Blick ins System KOMBau geworfen werden?\n\nBleibt in KOMBau alles wie gewohnt oder gibt es dort Ã„nderungen?\n\nDas GPEnS wird, wie auch das GPE immer gesammelt und montags versendet.\n\n1.58 Was ist mit den Kosten? Wir fahren einen Ersatzverkehr den wir eigentlich nicht fahren mÃ¼ssten? Senden wir Kosten an InfraGO. Sollte eine BauFplo versendet worden sein,\n\nmit 8 Wochen Vorlauf und BaumaÃŸnahme Ã¤ndert sich, sodass BauFplo ausfÃ¤llt.\n\nEs gilt die neue Vertragstrasse. Ein RÃ¼ckabwicklung zur ursprÃ¼nglichen Trasse ist nicht mehr\n\nvorgesehen. Die Bautrasse, die zur Regeltrasse geworden ist, kann innerhalb von drei Tagen\n\nkostenfrei storniert werden, danach kann im Gelegenheitsverkehr eine neue Trasse bestellt\n\nwerden. Es gibt allerdings keine Garantie, dass noch KapazitÃ¤ten verfÃ¼gbar sind.\n\n1.59 Wer bezahlt eigentlich die Trasse, wenn die BaumaÃŸnahme dann doch ausfÃ¤llt,\n\nnachdem FPE/NAÃ„/Fplo bereits versandt wurde?\n\nEs gilt die neue Vertragstrasse. Ein RÃ¼ckabwicklung zur ursprÃ¼nglichen Trasse ist nicht mehr\n\nvorgesehen. Die Bautrasse, die zur Regeltrasse geworden ist, kann innerhalb von drei Tagen\n\nkostenfrei storniert werden, danach kann im Gelegenheitsverkehr eine neue Trasse bestellt\n\nwerden. Es gibt allerdings keine Garantie, dass noch KapazitÃ¤ten verfÃ¼gbar sind.\n\n1.60 Wie ist das Vorgehen, wenn Stellungnahmen nur teilweise umgesetzt werden kÃ¶nnen? Beispiel: GPE: mittige TeilausfÃ¤lle -> Stellungnahme: Umleitungen -> FPE: Umleitungen in eine Richtung, mittige TeilausfÃ¤lle in die andere Richtung. Die UmlÃ¤ufe wÃ¼rden",256,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":15,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","c4808c60f9b7928ba8ce48ffe4d605d40d2c925c5c811e612575a43b55e645b8"],["chunk_429d7d421978cef60f661840","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",29,"Seite 15","in diesem Fall nicht mehr aufgehen. Eine StornomÃ¶glichkeit hilft dort aber auch nicht.\n\nAuszug aus den INB (2027) Abschnitt 3 Absatz 7:\n\nDie DB InfraGO AG prÃ¼ft stets, inwiefern eingegangene Stellungnahmen im bestmÃ¶glichen Umfang und im Rahmen eines Gesamtkonzeptes (Wechselwirkung zu anderen Stellungnehmenden) berÃ¼cksichtigt werden kÃ¶nnen. Hinsichtlich Stellungnahmen zur Anpassung des aktuellen\n\nPlanungsstands prÃ¼ft die DB InfraGO AG, inwiefern den WÃ¼nschen der Stellungnahmeberechtigten unter BerÃ¼cksichtigung der in Abs. 3 beschriebenen ZwÃ¤nge Rechnung getragen werden\n\nkann. Auf Basis der sich aus den Stellungnahmen abzuleiten den BegrÃ¼ndungen, prÃ¼ft die DB\n\nInfraGO AG zunÃ¤chst, inwiefern das bisherige Regelungskonzept angepasst werden muss. Sofern dies der Fall ist, Ã¼berarbeitet die DB InfraGO AG das Regelungskonzept. Derartige Ãœberarbeitungen kÃ¶nnen z. B. Ã„nderungen der Anzahl der ZÃ¼ge pro Verkehrsart auf der baubetroffenen Strecke oder Nutzung anderer / weiterer Umleitungsstrecken beinhalten.\n\n1.61 Wenn man ein GPE, GPEnS oder FPE ablehnt, erfolgt die netzseitige Stornierung der\n\nTrasse. AnschlieÃŸend kann man im Rahmen des GelV eine neue Trasse bestellen. Wie ist\n\nin diesem Fall der Ablauf des nachgelagerten Prozesses? Wie sind die zeitlichen Eckpunkte zur Bearbeitung und spÃ¤teren VerÃ¶ffentlichung dieser Trasse? Ist die Anmeldung\n\neiner neuen Trasse im GelV direkt nach Ablehnung mÃ¶glich oder erst ab z-8 vor der relevanten BaumaÃŸnahme? Was ist der spÃ¤teste Zeitpunkt, zu dem eine Bestellung einer\n\nneuen Trasse im GelV in diesen FÃ¤llen mÃ¶glich ist?\n\nNB 2027 Ziffer 4.2.2.4 gelten zum Fahrplan 2027 folgende Fristen im Gelegenheitsverkehr.\n\nSiehe Abschnitt in den genannten INB.\n\nV.IWF 41 Fragenkatalog 15",242,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":15,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","3b80d74c1150d5ec9b019bf31734b123b831ac29721301693e5f3b36d1453830"],["chunk_792707ccf68465c84983b7bb","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",30,"Seite 16","1.62 Bitte zeigen Sie auf, welches Fahrplanprodukt bei Prozessabbruch durch DB InfraGO dann wieder gilt: Prozessabbruch durch DB InfraGO zu folgendem Zeitpunkt: vor\n\nVersand GPE, nach Versand GPE und vor Versand GPEnS, nach Versand GPEnS und vor\n\nVersand FPE, nach Versand FPE und vor Versand BauFplo, nach Versand BauFplo.\n\nVor Versand GPE gilt die Regeltrasse. Nach Versand GPE und vor Versand GPEnS gilt die Regeltrasse. Nach Versand GPEnS und vor Versand FPE gilt die Regeltrasse. Nach Versand FPE\n\nund vor Versand BauFplo, gilt, dass der Bauprozess hier abgeschlossen ist. Die Bautrasse ist\n\ndie neue Regeltrasse und bleibt bestehen. Nach Versand der BauFplo gilt, dass der Bauprozess hier abgeschlossen ist, die Bautrasse ist die neue Regeltrasse und bleibt bestehen.\n\n1.63 Wird eine Leertrasse den regulÃ¤ren GPE-Prozess durchlaufen oder erfolgt hierfÃ¼r\n\neine NAÃ„ zur Leertrasse?\n\nAuch Leerzugtrassen kÃ¶nnen ein GPE erhalten, sofern sie vor Beginn der Bearbeitung der\n\nMaÃŸnahme bekannt sind.\n\nIst die Leerzugtrasse indirekt baubetroffen, wird in der Stellungnahme eine RÃ¼ckmeldung des\n\nEVUs benÃ¶tigt. Das EVU erhÃ¤lt im Anschluss fÃ¼r die indirekt betroffene Leerzugtrasse ein FPE.\n\n1.64 Wie werden kurzfristige Ã„nderungen nach z-24 kommuniziert? KÃ¶nnen EVU auf\n\nkurzfristige KapazitÃ¤tseinschrÃ¤nkungen nach GPE noch RÃ¼ckmeldung abgeben?\n\nINB 2027 Ril. 402.0305 Abschnitt 9 Absatz (3)\n\nKÃ¶nnen bestehende Fristen nicht eingehalten werden â€“ etwa, weil die BKE auf einer kurzfristig\n\nerforderlichen BaumaÃŸnahme beruht - so konsultiert die DB InfraGO AG die ZB und EIU umgehend (sofern keine Gefahr in Verzug). Diese haben einen Arbeitstag Zeit, um eine Stellungnahme abzugeben.",244,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":16,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","c0edfe969d7b2ebbb95f2077d0503bcd4020313ef8cc5ce64417c8e402e9e197"],["chunk_73aa1b1645f2a2582bcbf85a","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",31,"Seite 16","1.65 Wie kann sichergestellt werden, dass Vorgaben vom AufgabentrÃ¤ger (z.B. Anschlussverkehre, SchÃ¼lerverkehre) berÃ¼cksichtigt werden, sodass diese an bestimmten\n\nBetriebsstellen erreicht werden kÃ¶nnen.\n\nDie EVU haben die MÃ¶glichkeit, an den relevanten Bst. (Betriebsstellen), an denen Anschlussverkehre vorhanden sind, eine frÃ¼heste oder spÃ¤teste Zeit anzugeben, inklusive eines Kommentars auf der Betriebsstellenebene, warum die Einhaltung wichtig ist. (z.B. Anschluss der\n\nBus-Linie X muss erreicht werden)\n\n1.66 Aufgrund der unterschiedlichen Fristen (z-15 vs. z-24) erhalten wir ab September 10\n\nWochen lang jede Woche fÃ¼r 2 Planungswochen GPEs, ist das korrekt?\n\nJa das ist korrekt, es werden fÃ¼r 2 Planungswochen GPEs versendet.\n\n1.67 Wenn zwei ZÃ¼ge (z.B. SGV) an einer bestimmten Betriebsstelle ihren Wagenaustausch machen und eine gemeinsame Haltezeit von 30 Min. benÃ¶tigen, jetzt bekommt\n\nZug 1 ein GPE mit einer BKE von 60 Min. spÃ¤ter in dieser Betriebsstelle an.\n\nBekommt der Zug 2 auch ein GPE ab der gemeinsamen Betriebsstelle mit +60 Min. ?\n\nFÃ¼r den nicht baubetroffenen Zug erfolgt keine Bauausregelung. Hier ist eine Ã„nderungsbestellung durch den Kunden notwendig.\n\n1.68 Es kommt die Information, dass die Baustelle ausfÃ¤llt, nach der Stellungnahme aufs\n\nGPE und vor dem FPE. Wie gehen wir damit um? Bekommen wir eine Information, dass\n\nalle Regelungen zurÃ¼ckgezogen werden?\n\nSollte eine BaumaÃŸnahme vor dem FPE-Versand abgesagt werden und ist die Trasse dadurch\n\nnicht mehr baubetroffen, wird durch uns eine Nachricht gesendet, dass der Prozess abgebrochen wurde. Die Vertragstrasse gilt unverÃ¤ndert, d.h. ohne Baubetroffenheit, fort. Wir schicken\n\ndas letzte Fahrplanprodukt (GPE oder GPEnS) erneut, inkl. withdrawal-message.\n\nV.IWF 41 Fragenkatalog 16",248,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":16,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","190b8417f02e642ace8c7f5a5c8c92fcf5ac9dbc9ac8ff54dd75a26cf687b7af"],["chunk_b83080bca3883c10358ee9c9","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",32,"Seite 17","1.69 Sofern in der 4 KP. bis z-5 noch baubedingte Leertrassen/Zusatzleistungen bestellt\n\nwerden kÃ¶nnen, bis zu welchem Zeitpunkt muss diese Leertrasse dem EVU spÃ¤testens\n\nzur VerfÃ¼gung gestellt werden?\n\nDas muss laut den INB (2026) 4.2.2.4 Fristen fÃ¼r die Bearbeitung von Trassenanmeldungen\n\ninnerhalb von 5 Arbeitstagen erfolgen.\n\nInfrastrukturnutzungsbedingungen der DB InfraGO AG (INB) 2026\n\nV.IWF 41 Fragenkatalog 17",57,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":17,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","895a2eb194b55d834738b72cd1f6213d2abae9a4f2958fce58a82b02d36b3836"],["chunk_3b39bb6658c2849847f548d5","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",33,"Seite 18","Baubedingte Zusatzleistungen\n\n1.1 Wenn ein GPE von mehreren BKE betroffen ist, kÃ¶nnen wir davon ausgehen, dass bei\n\nLeerzugbestellungen die Angabe einer Rabatt-Nummer reicht? Es wird um ErlÃ¤uterung\n\nder Antwort gebeten.\n\nEs wird keine Rabattnummer mehr geben. Bei der Bestellung wird ein Verweis des EVUs auf\n\ndie PathID der Bautrasse erforderlich sein. Dieser wird als RelatedPlannedTransportID angegeben. ZusÃ¤tzlich muss beim NSP â€žverkehrsArtKundeZusatzâ€œ die AusprÃ¤gung â€žBaubedingteZusatzleistungâ€œ angegeben werden.\n\n1.2 Wir haben verstanden, dass die baubedingte Zusatzleistung auf die NAÃ„ beziehen. Ist\n\nes mÃ¶glich die Bestellungen auch schon zum Zeitpunkt ab GPE auszulÃ¶sen?\n\nJa, das ist mÃ¶glich. Die Empfehlung wÃ¤re aber, das so spÃ¤t wie mÃ¶glich zu tun.\n\n1.3 Wenn aufgrund der BKE zusÃ¤tzliche ÃœberfÃ¼hrungsfahrten (Leertrassen), Umleitungen\n\noder die Einrichtung von Bauelektranten (=Zusatzausstattung einer Serviceeinrichtung)\n\nerforderlich wird, Ã¼bernimmt dann DB InfraGO wie bislang bei unterjÃ¤hrigen BaumaÃŸnahmen die Kosten?\n\nJa, siehe dazu auch Ril.402.0305 â€“(INB 2027)- Abschnitt 11 Abs 2: Trassenanmeldungen baubedingter\n\nzusÃ¤tzlicher Leistungen (...) Hierunter fallen insbesondere zusÃ¤tzliche baubedingte Anmeldungen fÃ¼r\n\n- Zu- und AbfÃ¼hrungsfahrten zu einem Schienenersatzverkehr,\n\n- Drehfahrten,\n\n- Zu- und AbfÃ¼hrungsfahrten zu einer anderen als der gewÃ¶hnlichen Abstell- oder Tankanlage,\n\n- Zu- und AbfÃ¼hrungsfahrten von Triebfahrzeugen oder\n\n- zusÃ¤tzliche Verkehre auf Grund einer Ã„nderung der Zugcharakteristik (z.B. Ablasten auf\n\nGrund geringerer Grenzlast einer Umleitungsstrecke).",204,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":18,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","a2c8a49c58b5876a82ccfbb40e4a324e7bc9cb801801b8c8efe773484d08c5c9"],["chunk_05ab9f4a18fac43263880f5d","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",34,"Seite 18","1.4 Wir erwarten, dass bei Verfristung/Inkonsistenzen beim FPE/NAÃ„ nach T-5 noch kostenfreie Leerzug-Bestellungen vorgenommen werden kÃ¶nnen mit Rabattnummer? Bei einer nicht auszuschlieÃŸender Verfristung seitens InfraGO muss damit das EVU bei notwendigen Ã„nderungen bezahlen?\n\nUnser Ziel ist, dass das FPE fristgerecht versendet wird. Die Baubedingten Zusatzleistungen\n\nkÃ¶nnen nur bis z-5 (5 Wochen vor Baubeginn, nicht T-5) bestellt werden, ansonsten fallen Kosten an.\n\n1.5 Ist die Referenzierung des CRID der zugehÃ¶rigen Trasse (bspw. des GPEs) im NSP\n\nâ€žrabattNrâ€œ erwartet? Falls nein, welche Angabe wird in â€žrabattNrâ€œ genau erwartet?\n\nBei der Bestellung wird ein Verweis des EVUs auf die PathID der Bautrasse erforderlich sein.\n\nDieser wird als RelatedPlannedTransportID angegeben. ZusÃ¤tzlich muss beim NSP â€žverkehrs-\n\nArtKundeZusatzâ€œ die AusprÃ¤gung â€žBaubedingteZusatzleistungâ€œ angegeben werden.\n\n1.6 Da momentan die NV-Nummer auch Ã¼ber das NSP \"rabattNr\" exportiert wird, sprechen wir uns stark dafÃ¼r aus, ein anderes Feld fÃ¼r die baub. Zusatzleistung zu verwenden. Damit kÃ¶nnen wir sicherstellen die NV-Nummer aufrechtzuerhalten. Ist es mÃ¶glich\n\nein separates Feld zu verwenden? Wenn nicht, muss eine bestehende Rabattnr. Zum\n\nNeuverkehr bei FolgeauftrÃ¤gen immer wieder mitgeschickt werden?\n\nBei der Bestellung wird ein Verweis des EVUs auf die PathID der Bautrasse (FPE) erforderlich\n\nsein. Dieser wird als RelatedPlannedTransportID angegeben. ZusÃ¤tzlich muss beim NSP â€žverkehrsArtKundeZusatzâ€œ die AusprÃ¤gung â€žBaubedingteZusatzleistungâ€œ angegeben werden.\n\nV.IWF 41 Fragenkatalog 18",208,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":18,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","934c2d6bcd0a9f4fcdfb332272b16249de850daf54a7fa6feaa1bf4d0bc81a8b"],["chunk_d7746b1b5eee947f35147ac1","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",35,"Seite 19","1.7 Das NSP \"rabattNr\" hat momentan eine AusprÃ¤gung 0..5. Was ist, wenn mehr als 5\n\nBaubetroffenheiten inkl. Neuverkehrsnr. Angegeben werden mÃ¼ssten? (\"Reicht\" die Angabe einer Baureferenz?)\n\nBei der Bestellung wird ein Verweis des EVUs auf die PathID der Bautrasse erforderlich sein.\n\nDieser wird als RelatedPlannedTransportID angegeben. ZusÃ¤tzlich muss beim NSP â€žverkehrs-\n\nArtKundeZusatzâ€œ die AusprÃ¤gung â€žBaubedingteZusatzleistungâ€œ angegeben werden.\n\n1.8 Guten Tag. Wo werden zukÃ¼nftig im Prozess die baubedingten Zusatzleistungen verortet? Dazu konnten wir bisher noch keine Informationen finden.\n\nBei der Bestellung wird ein Verweis des EVUs auf die PathID der Bautrasse erforderlich sein.\n\nDieser wird als RelatedPlannedTransportID angegeben. ZusÃ¤tzlich muss beim NSP â€žverkehrs-\n\nArtKundeZusatzâ€œ die AusprÃ¤gung â€žBaubedingteZusatzleistungâ€œ angegeben werden. Weitere Informationen finden Sie in den FAQ 4. Konsultationsphase, in der Ril. 402.0305 INB 2027 und\n\nunter der Website Fahrplan: EVU-Schnittstelle Archiv Dokumentation Anlage 10.\n\n1.9 Findet die Bestellung von baubedingten Zusatzleistungen Ã¼ber das Bestellsystem\n\nstatt und wird dann Ã¼ber die Schnittstelle intern fÃ¼r die Erstellung der Fahrplanprodukte\n\nÃ¼bermittelt?\n\nEs besteht Kanalzwang. Erfolgt die Bestellung Ã¼ber PathOS wird das Angebot zu PathOS gesendet, erfolgt die Bestellung Ã¼ber die Schnittstelle, wird das Angebot an die Schnittstelle versendet. Bei Neubestellung einer baubedingten Zusatzleistung muss bei verkehrsArtKundeZusatz â€žBaubedingteZusatzleistungâ€œ angegeben werden. ZusÃ¤tzlich muss eine Referenz zur PathID des FPEs angegeben werden.\n\n1.10 Wenn fÃ¼r abgestimmte BaukapazitÃ¤tseinschrÃ¤nkungen (BKE) 4, 6, 7 und 8 im Netzfahrplan zusÃ¤tzliche Leistungen, wie beispielsweise Leerfahrten, erforderlich werden:",225,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":19,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","4c8000a86238351ad7b24194a189f1b0b3127169af8582452b8248a0d2ea3575"],["chunk_a2c30fb22e2de9b89aee6149","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",36,"Seite 19","Werde diese ohne Anrechnung von Trassenkosten bereitgestellt?\n\nNein. FÃ¼r Leistungen, die aufgrund bereits im Netzfahrplan eingeplanter BaumaÃŸnahmen entstehen â€“ etwa zusÃ¤tzliche Leerfahrten â€“ existiert kein vergleichbares Vorgehen zur kostenfreien\n\nBereitstellung wie bei unterjÃ¤hrigen BaumaÃŸnahmen.\n\n1.11 Wie werden benÃ¶tigte Leertrassen mit Baubezug im Netzfahrplan bestellt? Wie wird\n\nder Baubezug hergestellt damit kein Trassenentgelt berechnet wird und mÃ¼ssen diese\n\nLeertrassen in der NEP 1 Phase bestellt werden oder wird es grÃ¶ÃŸere Bestellfristen geben?\n\nFÃ¼r Leistungen, die aufgrund bereits im Netzfahrplan eingeplanter BaumaÃŸnahmen entstehen â€“\n\netwa zusÃ¤tzliche Leerfahrten â€“ existiert kein vergleichbares Vorgehen zur kostenfreien Bereitstellung wie bei unterjÃ¤hrigen BaumaÃŸnahmen.\n\n1.12 Wie gestalten sich die Fristen fÃ¼r die Bestellung der Ã¼berjÃ¤hrigen baubedingten Zusatztrassen?\n\nFÃ¼r Leistungen, die aufgrund bereits im Netzfahrplan eingeplanter BaumaÃŸnahmen entstehen â€“\n\netwa zusÃ¤tzliche Leerfahrten â€“ existiert kein vergleichbares Vorgehen zur kostenfreien Bereitstellung wie bei unterjÃ¤hrigen BaumaÃŸnahmen.\n\n1.13 Wie werden kostenfreie baubedingte Leerfahrten bei Ã¼berjÃ¤hriger Bauplanung berÃ¼cksichtigt?\n\nFÃ¼r Leistungen, die aufgrund bereits im Netzfahrplan eingeplanter BaumaÃŸnahmen entstehen â€“\n\netwa zusÃ¤tzliche Leerfahrten â€“ existiert kein vergleichbares Vorgehen zur kostenfreien Bereitstellung wie bei unterjÃ¤hrigen BaumaÃŸnahmen.\n\nV.IWF 41 Fragenkatalog 19",176,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":19,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","613bef880377f385a0c2ca1d2e6625e1ab962cea43b10a66f90f82bc2a536a11"],["chunk_083c6a1b9cca7c8687b31565","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",37,"Seite 20","1.14 Wenn nur SE/IA von einem BKE/BAE betroffen sind, kann man als EVU bis zu z-18\n\nein FPE fÃ¼r dadurch entstehende baubedingte zusÃ¤tzliche Leistungen beantragen. Wo\n\nund wie erfolgt die Beantragung des FPE (pathOS oder KOMBau?), auch im Hinblick auf\n\ndie dann mit z-14 folgende 3-wÃ¶chige Stellungnahme-MÃ¶glichkeit?\n\nSofern dem Zugangsberechtigten im Kontext der baubedingten AnlageneinschrÃ¤nkung (BAE)\n\nein Grobplanungsergebnis (GPE) vorliegt, kann die Bestellung einer baubedingten Neuleistung\n\nunter Bezugnahme auf die entsprechende PathID des betroffenen Zuges erfolgen.\n\nFÃ¼r FÃ¤lle, in denen eine BAE ohne vorheriges GPE vorliegt, besteht ebenfalls die MÃ¶glichkeit,\n\nbaubedingte Neuleitungen zu bestellen. In diesen FÃ¤llen erfolgt die Bestellung Ã¼ber die Ãœbermittlung der entsprechenden PathID. Wir bitten hierbei ergÃ¤nzend darum, im Bestellprozess in\n\npathOS die zugehÃ¶rige BAE anzugeben, um eine eineindeutige Zuordnung und Bearbeitung sicherzustellen.\n\nV.IWF 41 Fragenkatalog 20",130,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":20,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","f7b043d689fca88950980781ef10aff69eb56f34d995676fcbbc376f62dd119c"],["chunk_55627cea71dd9749e88ac56e","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",38,"Seite 21","Ã„nderungsbestellung\n\n1.1 Kann die InfraGO ausschlieÃŸen, dass zwischenT-24 und T-8 netzausgelÃ¶ste Ã„nderungen (nicht uj Bau) gesendet werden?\n\nAuszug INB 2027 - Ril 402.0305 Abschnitt 10 Absatz 7\n\nÃ„nderungsbestellungen von baubetroffenen Trassen (7)\n\nDie Bearbeitungsphase von baubetroffenen Trassen erstreckt sich im Zeitraum z-29 bis zum\n\nVersand des FPEs / der NAÃ„. Die DB InfraGO AG fÃ¼hrt keine Bearbeitung von Ã„nderungsbestellungen in diesem Zeitraum fÃ¼r baubetroffene Trassen durch, sobald sich diese bereits in der\n\nkonkreten Bearbeitung fÃ¼r eine Baufahrplanregelung (Erstellung GPE, Erstellung GPEnS bzw.\n\nErstellung FPE) befinden. Ãœber eine etwaige Baubetroffenheit werden ZB nach AuslÃ¶sung einer\n\nÃ„nderungsbestellung Ã¼ber den Grad der Baubetroffenheit durch eine Nichtkonstruierbarkeit\n\n(â€žPathDetailMessageâ€œ mit dem TypeofInformation 21 â€žno alternative availableâ€œ informiert.\n\nDadurch erfÃ¤hrt der ZB gleich-zeitig, dass und fÃ¼r welchen Zeitraum sich die baubetroffene\n\nTrasse in der konkreten Bearbeitung befindet und somit eine Ã„nderungsbestellung zu diesem\n\nZeitpunkt nicht mÃ¶glich ist. FÃ¼r den nicht baubetroffenen Zeitraum erfolgt die Bearbeitung der\n\neingegangenen Ã„nderungsbestellung. Sobald der einzelne Bearbeitungsschritt im Baufahrplanprozess abgeschlossen ist, werden Ã„nderungsbestellungen zur Bearbeitung wieder angenommen. Die ZB haben die MÃ¶glichkeit zu den baubetroffenen Trassen, fÃ¼r die eine Nichtkonstruierbarkeit vor der VerÃ¶ffentlichung des GPE versendet wurde, im Rahmen der Stellungnahme zum\n\nGPE, Ã„nderungswÃ¼nsche fÃ¼r den baubetroffenen Zeitraum der DB InfraGO AG mitzuteilen.\n\nNicht baubetroffene ZeitrÃ¤ume und Verkehrstage sind von dieser Regelung also nicht betroffen.\n\nEbenso werden Ã„nderungsbestellungen bearbeitet und Trassenangebote erstellt, bei denen die",224,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":21,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","732b05cec353fa0e765d2144b667a63047dd205dee07c580f6a1a3d7b900de3d"],["chunk_2c75598fca26eac2c300b304","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",39,"Seite 21","konkrete Bearbeitung fÃ¼r eine Baufahrplanregelung noch nicht begonnen wurde (auch nach z-\n\n29) oder das FPE bereits vorfristig versendet wurde.\n\n1.2 WÃ¼rde dies bedeuten, dass die Prozesse des Jahresfahrplans und des Baufahrplans\n\nnicht mehr separat laufen und dann auf die Ã„nderungsbestellung keine BestÃ¤tigung\n\nkÃ¤me, sondern nur das FPE?\n\nAuszug INB 2027 - Ril 402.0305 Abschnitt 10 Absatz 7\n\n1.3 Kann es sein, dass nach der baubedingten NAÃ„ eine weitere NAÃ„ zur Ã„nderungsbestellung kommt?\n\nEs wird nach der NAÃ„ nicht automatisch eine weitere NAÃ„ zur Ã„nderungsbestellung geben.\n\nWird die NAÃ„ nicht storniert, kÃ¶nnen ZB Ã¼ber das Bestellsystem wieder Ã„nderungsbestellungen\n\nfÃ¼r den baubetroffenen Zeitraum auslÃ¶sen.\n\n1.4 Wie werden unterjÃ¤hrige RegeltrassenÃ¤nderungen und Neuverkehre gehandhabt (BerÃ¼cksichtigung in BKE 4, 6, 7, 8)?\n\nWenn die BaumaÃŸnahmen bereits im Netzfahrplan berÃ¼cksichtigt sind, werden diese bei Ã„nderungsbestellungen und Neubestellungen im GelV (Gelegenheitsverkehr) berÃ¼cksichtigt werden.\n\n1.5 Wie soll mit der ParallelitÃ¤t Ã„nderungsbestellung unterjÃ¤hriger Bauprozess umgegangen werden?\n\nAuszug INB 2027 - Ril 402.0305 Abschnitt 10 Absatz 7\n\nV.IWF 41 Fragenkatalog 21",162,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":21,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","ac0d494ed564cf0feb7ea79e3a0ca68f8f30b82808222d41f55f674835ac4cc4"]]');
