INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_5e8791fc03ae973db8a7c467","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",40,"Seite 22","1.6 UjBau bei Neubestellungen <T-29: Bei Neubestellungen von ZÃ¼gen im NFPL nach T-\n\n29 - wie kommen dann GPE und FPE-Informationen auf die ZÃ¼ge? (T-x = Wochen)\n\nINB 2027 Ril 402.0305 Abschnitt 8 Abs. 2\n\nBereitstellung FPE fÃ¼r BKE der zweiten und dritten Konsultationsphase fÃ¼r Trassen aus NEP II\n\nDie DB InfraGO AG stellt fÃ¼r BKE aus der zweiten und dritten Konsultationsphase das FPE fÃ¼r\n\nTrassen mit Verkehrstagen zwischen dem Fahrplanwechsel und 28. bzw. 29. Februar, welche\n\nzur zweiten Netzfahrplanerstellungsphase angemeldet wurden, bis acht Wochen (SPV) bzw.\n\nfÃ¼nf Wochen (SGV) vor Baubeginn innerhalb der betroffenen Bauwoche zur VerfÃ¼gung. Die DB\n\nInfraGO AG strebt an, FPE des SGV bis acht Wochen, spÃ¤testens jedoch fÃ¼nf Wochen vor Baubeginn innerhalb der betroffenen Bauwoche zur VerfÃ¼gung zu stellen.\n\nINB 2027 Ril 402.0305 Abschnitt 8 Abs. 4\n\nBereitstellung FPE fÃ¼r BKE der zweiten und dritten Konsultationsphase aus NEP I\n\nFÃ¼r BKE, die in der zweiten und dritten Konsultationsphase behandelt wurden und bis 28. bzw.\n\n29. Februar des aktuellen Fahrplanjahres beginnen, stellt die DB InfraGO AG den betroffenen\n\nZB ein GPE bis spÃ¤testens 15 Wochen vor Beginn der betroffenen Bauwoche zur VerfÃ¼gung\n\n(Ausnahmen siehe Abs. 2). Die ZB haben drei Wochen Zeit fÃ¼r eine Stellungnahme. Diese kann\n\nsich ausschlieÃŸlich auf die Inhalte des GPE beziehen, da die zugrunde liegende BKE zum Versandzeitpunkt des GPE bereits konsultiert wurde.\n\n1.7 Welche MÃ¶glichkeit haben EVUs die Baubetroffenheit festzustellen, wenn ein GPE\n\nnoch nicht oder verfristet vorliegt?\n\nDie bekannten BKE sind in der KOMBau hinterlegt und kÃ¶nnen dort eingesehen werden, z.B.\n\nder Zeitraum und die Ã¶rtliche Lage.",257,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":22,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","809a86d7028e69cd1b979257763914c6917ae7c14fa5983a94ee73583cdc8b9d"],["chunk_752b9ec82426f30158055afc","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",41,"Seite 22","1.8 Wird in dem Zusammenhang darÃ¼ber nachgedacht die OIM zum Zeitpunkt z-29 wieder/doch einzufÃ¼hren, um Seitens DB InfraGO Ã¼ber die Baubetroffenheit zu informieren?\n\nFÃ¼r den Migrationszeitraum keine Umsetzung der OIM geplant. Die OIM kommt nicht vor der\n\nvollstÃ¤ndigen EinfÃ¼hrung TTT.\n\n1.9 SchlieÃŸt DB InfraGO netzausgelÃ¶ste Ã„nderungen (unabhÃ¤ngig von Bau) im Zeitraum\n\nz-29 bis z-8 generell aus? Wenn nicht, welche Regelung/Prozess gibt es dazu?\n\nNein, es kann nicht ausgeschlossen werden, dass wÃ¤hrend der Bearbeitungszeit im unterjÃ¤hrigen Bau, keine weiteren netzausgelÃ¶sten Ã„nderungen verarbeitet und gesendet werden.\n\n1.10 Wenn wir Ã„nderungsbestellungen von baubetroffenen Trassen nicht zulassen, dann\n\nsind sie diskriminiert gegenÃ¼ber denen, die einfach im GelV Trassen bestellen.\n\nEs gelten die Regelungen der INB. Jedes EVU hat die MÃ¶glichkeit Ã¼ber den GelV Trassen zu\n\nbestellen.\n\n1.11 In der Stellungnahme aufs GPE kÃ¶nnen WÃ¼nsche zu Ã„nderungen mit angegeben\n\nwerden: Sind fÃ¼r diese Ã„nderungswÃ¼nsche beim GPE alle notwendigen Attribute in der\n\nKOMBau vorhanden?\n\nIn der KOMBau sind fÃ¼r die PRM (PathRequestMessage) alle in Anlage 10 aufgefÃ¼hrten Attribute nutzbar.\n\nhttps://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/taf-taptsi/evu_schnittstelle-11089208#\n\nSiehe Anlage 1 und Anlage 10.\n\n1.12 Was passiert bei Prozessabbruch? Welche Trasse, Vertrag oder Ã„nderungsbestellung erhÃ¤lt das EVU zurÃ¼ck (wenn bei GPE mit angegeben)?\n\nBei Prozessabbruch gilt die ursprÃ¼ngliche Vertragstrasse. Eine erneute Ã„nderungsbestellung ist\n\nin diesem Fall notwendig.\n\nV.IWF 41 Fragenkatalog 22",207,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":22,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","5a47509e2721683c414459f33c1590df4656a5b80b40b7d1658cbf5664f3cdec"],["chunk_ad0d1a754e6770a664ae15fb","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",42,"Seite 23","1.13 Wie lÃ¤uft der Prozess bei einer MaÃŸnahme nach â€žNr. 14â€œ ANNEX VII?\n\nSobald eine Trasse baubetroffen ist, ist eine Ã„nderungsbestellung nicht mÃ¶glich.\n\n1.14 Was passiert, wenn die Fristen FPE nicht gehalten werden (beachte auch Widerspruch zu Ril 402.0305 Abschnitt 8 z-5/z-8), sind dadurch bei Ã„nderungsbestellung wÃ¶chentlich rollierende Zeitscheiben erforderlich (Mehraufwand?), momentan gibt es hier\n\nunterschiedliche Fristen.\n\nJa, es mÃ¼ssen dann neue Ã„nderungsbestellungen ausgelÃ¶st werden.\n\n1.15 Sind Ã„nderungsbestellungen wÃ¤hrend der Bearbeitungsfrist naÃ„(3 WT) wieder mÃ¶glich?\n\nWir beabsichtigen eine Ã„nderung der INB 2027 Ril. 402.305 Abs. 8 (6). Es gibt keinen Ablehnen Button, sondern die Stornierung erfolgt im Regelprozess. Eine NAÃ„ gilt als neuer Vertragszustand. Die neue Vertragstrasse kann innerhalb von 3 Arbeitstagen kostenfrei storniert werden. Dadurch besteht die beschriebene Problemstellung nicht.\n\n1.16 Wir gehen davon aus, dass Ã„nderungsbestellungen, die einen baubetroffenen Zeitraum tangieren technisch zurÃ¼ckgewiesen werden.\n\nEs gibt eine RÃ¼ckmeldung nach Bearbeitung der Ã„nderungsbestellung. Hier erkennt man, an\n\nwelchen Tagen die Ã„nderungsbestellung umgesetzt werden kann und an welchen eine Bautrasse angelegt wird. FÃ¼r den Zeitraum der Bautrasse wird eine â€žNichtkonstruierbarkeitâ€œ gesendet.\n\nDie Nichtkonstruierbarkeit auf Ã„nderungsbestellung wird im Hauptschnittstellendokument auf\n\nSeite 44 im Schaubild des TrassenÃ¤nderungsprozess beschrieben. (Versand dieser Nichtkonstruierbarkeit ist innerhalb von 5 Arbeitstagen)\n\n1.17 Wie kann das EVU im Zeitraum z-29 bis z-24 erkennen das eine Ã„nderungsbestellung nicht zulÃ¤ssig ist?\n\nDie technische Umsetzung erfolgt. FÃ¼r den Zeitraum der Bautrasse wird eine â€žNichtkonstruierbarkeitâ€œ gesendet.",224,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":23,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","b3fc027295919e1d8f8d74551737a9566e678267b37361ee23804e96233a3987"],["chunk_8697ca32c96f97c47fb78536","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",43,"Seite 23","Die Nichtkonstruierbarkeit auf Ã„nderungsbestellung wird im Hauptschnittstellendokument auf\n\nSeite 44 im Schaubild des TrassenÃ¤nderungsprozess beschrieben. Versand dieser Nichtkonstruierbarkeit ist innerhalb von 5 Arbeitstagen)\n\n1.18 Trifft die Bearbeitungsphase z-29 bis z-8 auch fÃ¼r ZÃ¼ge die in der NEP 2 und im Gelegenheitsfahrplan bestellt wurden zu? Konkret: Die NEP 2 endet fÃ¼r den Fahrplan am\n\n13.07.26 und die ENP werden am 28.09. versandt. Wenn nach ENP NEP 2 eine Ã„nderungsbestellung durchgefÃ¼hrt wird, trifft der Absatz 10, Abschnitt 6 dann zu? Gleiche\n\nFrage fÃ¼r den Gelegenheitsverkehr: Es werden ZÃ¼ge nach dem 13.07. bestellt, dann erhalten wir nach Abschluss ENP NEP 2 (28.09.26) die ersten Angebote. Wenn nach Annahme der Angebote im GelV Ã„nderungen vorgenommen werden, trifft dann ebenfalls\n\nder Absatz 10, Abschnitt 6 dann zu?\n\nAlle TrassenvertrÃ¤ge nach z-29 kÃ¶nnen nur bei einer nicht Baubetroffenheit eine Ã„nderungsbestellung erhalten.\n\n1.19 Was ist mit einer Ã„nderungsbestellung im GÃ¼terverkehr (SGV), wenn diese zwischen\n\nz-8 und z-5 eingeht?\n\nDie INB 2027 wurden dafÃ¼r angepasst. Nach Versand des FPE/NAÃ„ ist eine Ã„nderungsbestellung wieder mÃ¶glich.\n\nV.IWF 41 Fragenkatalog 23",170,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":23,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","2fba4b20be88a9f26d4b2fc092176f07ddc0103e72c1c1feb6843af2e78ea1db"],["chunk_5d70ce60bc9926bd4c00a80c","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",44,"Seite 24","1.20 Wie und mit welchem Vorlauf erfolgt die Umbestellung der Zugcharakteristik von Regeltrassen, die sich aufgrund von BaumaÃŸnahmen ergeben? z.B. auÃŸerplanmÃ¤ÃŸige\n\nDoppeltraktionen oder abweichender Fahrzeugeinsatz, um AusfÃ¤lle auszugleichen.\n\nWird wÃ¤hrend der Konsultations-Stellungnahmephase zu einem GPE umlaufbedingt eine Anpassung der Zugcharakteristik erforderlich und hierzu Stellungnahme vom ZB abgegeben, wird\n\nlediglich das GPE bzw. in das GPEnS sowie ggf. das FPE die geÃ¤nderte Zugcharakteristik aufgenommen, sofern diese umsetzbar ist angepasst. Wird eine berechtigte Ã„nderung nach dem\n\nVersand des FPE ausgelÃ¶st dieser Konsultationsphase notwendig, wird eine neue FPE, NAÃ„\n\nund digitale BauFplo mit der geÃ¤nderten Zugcharakteristik ausgestellt, sofern umsetzbar. Alternativ kann eine Ã„nderungsbestellung getÃ¤tigt werden. Es wird auf Abschnitt 10 Abs. 7 der\n\nRichtlinie 402.0305 verwiesen.\n\nV.IWF 41 Fragenkatalog 24",117,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":24,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","ea182c2fbe292d98d309b11c50e18ac323aa7fd0fb6dd54a4e416d5a8bdc73e7"],["chunk_0f25d1de1f7ba67618c9575a","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",45,"Seite 25","International\n\n1.1 Wie lÃ¤uft die Abstimmung mit anderen EIU, die noch klassisch in BaumaÃŸnahmen\n\nausregeln? (z.B. Ã–BB Infra)\n\nDa der ANNEX VII nur Ã¼berjÃ¤hrig die Internationale Koordination fordert, abgeleitet sind folgenden Fristen nach Ril 402.0305 - zu x-39, x-31 ,x-27(1.Konsultationsphase) und x-19, x-15\n\n(2.Konsultationsphase) , werden wir dieses Thema derzeit nicht priorisieren kÃ¶nnen. Daher gibt\n\nes vorerst keine VerÃ¤nderung zum bisherigen Vorgehen. Siehe dazu auch Ril 402.0305 in Abschnitt 15. Ein Workshop hat stattgefunden.\n\n1.2 Wird es bei der GPE/FPE- Bearbeitung ein Masterprinzip geben, insbesondere bei\n\nlanglaufenden Fernlagen wie beispielsweise Taulov( DK) - Gallarate (I) weil viele DB I RB\n\n`en tangiert sind?\n\nDa der ANNEX VII nur Ã¼berjÃ¤hrig die Internationale Koordination fordert, abgeleitet sind folgenden Fristen nach Ril 402.0305 - zu x-39, x-31 ,x-27(1.Konsultationsphase)und x-19, x-15\n\n(2.Konsultationsphase) , werden wir dieses Thema derzeit nicht priorisieren kÃ¶nnen. Daher gibt\n\nes vorerst keine VerÃ¤nderung zum bisherigen Vorgehen. Siehe dazu auch Ril 402.0305 in Abschnitt 15. Ein Workshop hat stattgefunden.\n\nV.IWF 41 Fragenkatalog 25",162,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":25,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","c6b5d2d6e95330559b4e55b1d6af4283f06a5c893fa19d5893a51be7b593a4a0"],["chunk_803493324a28bb7b507fd6e5","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",46,"Seite 26","Mittiger Teilausfall SEV (Schienenersatzverkehr)\n\n1.1 Wie verhÃ¤lt es sich mit TeilausfÃ¤llen am Anfang und am Ende, gibt es dann einen\n\nneuen TrainActivityCode oder eine verkÃ¼rzte PathDetailsMessage?\n\nBei TeilausfÃ¤llen am Anfang und Ende der Trasse wird eine verkÃ¼rzte PDM versendet.\n\n1.2 Es gibt Umfangreiche Zugnummernregeln im Jahresfahrplan. Wenn andere Regeln\n\ngreifen bzgl. ZugnummernÃ¤nderung gilt das Gezeigte nicht?\n\nDie Umnummerung gilt bei einem beliebigen Zugteil. Ansonsten gelten die bisherigen Zugnummernregelungen nach Ril 402.0209. Das Hauptschnittstellendokument wurde entsprechend angepasst.\n\n1.3 Die Information der Zugnummer wird bei einem mittigen Teilausfall SEV im GPE benÃ¶tigt. BehÃ¤lt das Zugnummernkontingent das EVU?\n\nIm GPE wird eine Trasse gesendet, mit einer betrieblichen Zugnummer. Im GPE werden die\n\nausfallenden Betriebsstellen markiert. Die Aufteilung erfolgt erst im nÃ¤chsten Produkt, wodurch\n\nes dann die zweite Zugnummer erhÃ¤lt. Es Ã¤ndert sich nichts an der bisherigen Zugnummernvergabe.\n\n1.4 Welche Fahrplanprodukte erhalten wir bei einem mittigen Teilausfall mit SEV und wie\n\nist das in KOMBau einzugeben?\n\nIm Prozessschritt GPE erhalten Kunden im Fall eines mittigen Teilausfalls ein GPE, in dem die\n\nausfallenden Bst. markiert sind. Bei Bedarf kÃ¶nnen die Kunden im Freitextfeld auf Nachrichtenebene angeben, welcher Zugteil umgenummert werden soll. Eisenbahnverkehrsunternehmen\n\nmit Bauzugnummernkontingent geben zusÃ¤tzlich die zu verwendende Zugnummer an.\n\nIm weiteren Verlauf wird die Trasse in zwei aufgeteilt und zwei Folgefahrplanprodukte gesendet.\n\n1.5 Wie ist der Umgang in der KOMBau mit einem Nachtsprung bei mittigem Teilausfall?\n\nDie komplette Bautrasse wird durch die DB InfraGO in Form einer netzausgelÃ¶sten Stornierung,",236,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":26,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","6348e0a26a2aefa7a886d65aeaccac16c3c45467c89a1cf8a99285b03c659088"],["chunk_af501c779859961ccfc3b396","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",47,"Seite 26","kurz NAS storniert. Danach ist die Bestellung beider Zugteile mit jeweils neuer Zugnummer\n\nÃ¼ber den Gelegenheitsverkehr notwendig. HierfÃ¼r gewÃ¤hrleistet die DB InfraGO, dass die bisherige Trassenlage fÃ¼r einen Zeitraum von sieben Arbeitstagen vorgehalten wird. Erfolgt keine\n\nNeubestellung dieser Trasse innerhalb von sieben Arbeitstagen, wird die Trasse als vollstÃ¤ndig\n\nausgefallen im Rahmen der weiteren Bearbeitung betrachtet.\n\nV.IWF 41 Fragenkatalog 26",59,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":26,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","2bb4c33d9baa8ecd0d2a0e3c72847aa8e76d90f6eccea12fd88f8bc0bb912bc1"],["chunk_11702f7d5859c8f3e9e3be6b","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",48,"Seite 27","Digitale BauFplo\n\n1.1 Wir als EVU wÃ¼rden dann idealerweise wie folgt arbeiten: Alles, was mit Trasse und\n\nFahrplan zu tun hat immer aus den NAÃ„/ PDM nehmen. Da gibt es fertige Adapter.\n\nDie NAÃ„ ist ein vertragliches Dokument und enthÃ¤lt nicht alle relevanten betrieblichen Regelungen fÃ¼r eine Zugfahrt. Das Fahrplanprodukt BauFplo ist auch im Annex VII Prozess die offizielle\n\nBauFahrplananordnung.\n\n1.2 Wenn eine neue BauFplo kommt, gibt es dann auch die MÃ¶glichkeit, zeitgleich dazu\n\neine netzausgelÃ¶ste Ã„nderung (NAÃ„) zu versenden?\n\nNach Versand der NAÃ„ wird es zu z-3 eine gÃ¼ltige BauFplo in PDF-Format geben, da diese betrieblich relevante Regelungen enthÃ¤lt.\n\n1.3 Ist die NAÃ„ als Resultat des Bauprozesses vollstÃ¤ndig im EBuLa Fahrplan abgebildet? Sind damit die zusÃ¤tzlichen Fplo Ìen obsolet?\n\nDie NAÃ„ ist ein vertragliches Dokument und enthÃ¤lt nicht alle relevanten betrieblichen Regelungen fÃ¼r eine Zugfahrt. Das Fahrplanprodukt BauFplo ist die offizielle BauFahrplananordnung\n\n(BauFplo).\n\n1.4 Wir haben verstanden, dass FPLOen mit der EinfÃ¼hrung von Annex und TTT planerisch nicht mehr relevant sind und damit in unseren Planungssystemen kÃ¼nftig nicht verarbeitet werden mÃ¼ssen, weil durch InfraGO fÃ¼r den Bauprozess (Konsultationsphase 4.\n\nKP - Annex) immer eine NAÃ„/FPE identisch zur folgenden FPLO versandt wird.\n\nDie NAÃ„ ist ein vertragliches Dokument und enthÃ¤lt nicht alle relevanten betrieblichen Regelungen fÃ¼r eine Zugfahrt. Das Fahrplanprodukt BauFplo ist die offizielle Baufahrplananordnung.\n\n1.5 Wird mit EinfÃ¼hrung der digitalen BauFplo auch die QualitÃ¤t dieses Dokuments erhÃ¶ht (keine rÃ¤umlichen + zeitlichen Inkonsistenzen mehr; konkretes Ausweisen von Behandlungshalten an Betriebsstellen, z.B. zwingend Richtungswechsel)?",243,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":27,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","3d82977edfbb0eae2fe5f5b36237943a485ec76c9912fba383b1fd297e44ad8c"],["chunk_8906854068d55bae2c0b319c","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",49,"Seite 27","Die QualitÃ¤t des Dokuments wird auf Grund der automatisierten Erstellung erhÃ¶ht. Mit der EinfÃ¼hrung von TAF/TAP-TSI und Annex VII wird es im FPE keine rÃ¤umlichen Inkonsistenzen mehr\n\ngeben und somit wÃ¼rden sie auch nicht in der BauFplo ersichtlich sein. Zeitliche Inkonsistenzen\n\nkÃ¶nnen wir aktuell leider nicht ausschlieÃŸen. An dieser Thematik arbeiten wir weiterhin.\n\n1.6 Wird ein genauer Zeitpunkt festgelegt, in welcher Frist die Bau-Fplos versendet werden? Aktuell erhalten wir immer wieder Fplos, die sehr kurzfristig sind. Teilweise kommen sie sogar erst Freitagnachmittag.\n\nEs gelten die im Prozess definierten Fristen.\n\n1.7 KÃ¶nnen bei einer BauFplo Inkonsistenzen (rÃ¤umlich und zeitlich) ausgeschlossen\n\nwerden oder wird es In-konsistenzen noch geben. Wenn, ja wie werden sie dargestellt?\n\nDie QualitÃ¤t des Dokuments wird auf Grund der automatisierten Erstellung erhÃ¶ht. Mit der EinfÃ¼hrung von TAF/TAP-TSI und Annex VII wird es im FPE keine rÃ¤umlichen Inkonsistenzen mehr\n\ngeben und somit wÃ¼rden sie auch nicht in der BauFplo ersichtlich sein. Zeitliche Inkonsistenzen\n\nkÃ¶nnen wir aktuell leider nicht ausschlieÃŸen. An dieser Thematik arbeiten wir weiterhin.\n\n1.8 Werden mit der BauFplo zeitlich und rÃ¤umlich konsistente ZuglÃ¤ufe erzeugt und Ã¼bergeben?\n\nDie QualitÃ¤t des Dokuments wird auf Grund der automatisierten Erstellung erhÃ¶ht. Mit der EinfÃ¼hrung von TAF/TAP-TSI und Annex VII wird es im FPE keine rÃ¤umlichen Inkonsistenzen mehr\n\ngeben und somit wÃ¼rden sie auch nicht in der BauFplo ersichtlich sein. Zeitliche Inkonsistenzen\n\nkÃ¶nnen wir aktuell leider nicht ausschlieÃŸen. An dieser Thematik arbeiten wir weiterhin.\n\nV.IWF 41 Fragenkatalog 27",235,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":27,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","59bdda61c67e0e3f8a22893d2429bb75e26f18ec42951ed5bb64d69c2e6369ef"],["chunk_6ef7ab9e9f0dfe301f0becb0","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",50,"Seite 28","1.9 Wenn jeder Regionalbereich sauber konstruieren muss, mÃ¼ssen also kÃ¼nftig doch\n\nauch Regionalbereiche Teile erstellen, in die die ZÃ¼ge einfach mit einer VerfrÃ¼hung/-\n\nspÃ¤tung eingebrochen sind. Was passiert bei fehlenden KapazitÃ¤ten bei verschobenen\n\nLagen? Resultierende TeilausfÃ¤lle denkbar?\n\nDie QualitÃ¤t des Dokuments wird auf Grund der automatisierten Erstellung erhÃ¶ht. Mit der EinfÃ¼hrung von TAF/TAP-TSI und Annex VII wird es im FPE keine rÃ¤umlichen Inkonsistenzen mehr\n\ngeben und somit wÃ¼rden sie auch nicht in der BauFplo ersichtlich sein. Zeitliche Inkonsistenzen\n\nkÃ¶nnen wir aktuell leider nicht ausschlieÃŸen. An dieser Thematik arbeiten wir weiterhin.\n\n1.10 Stehen zukÃ¼nftig die Informationen aus der BauFplo auch in einem TAF/TAP TSI-\n\nFormat und mit den TAF/TAP TSI Identifier (Path- und TrainIDs, PLC, etc?) zu VerfÃ¼gung?\n\nAuf der BauFplo wird es zum aktuellen Kenntnisstand keine TTT-Identifier geben, da die Spezifikation zu TTT keine Vorgaben zur BauFplo macht.\n\n1.11 Sind weitere Endpunkte in der API geplant, z.B. um EinsprÃ¼che zu eine NAÃ„ abzugeben?\n\nIm Kontext der digitalen BauFplo fokussieren wir uns auf den automatisierten Versand der Bau-\n\nFplo an das EVU und den Betrieb, insbesondere dem TriebfahrzeugfÃ¼hrenden. Die BauFplo hat\n\nden Fokus auf der betrieblichen DurchfÃ¼hrung. Die GPE/FPE und netzausgelÃ¶ste Ã„nderung erfolgen im Rahmen des vorgelagerten Prozesses.\n\n1.12 Gibt es im Hochlauf fÃ¼r BauFploen auch ZvFen?\n\nZvFen wird es auch im Fahrplanjahr 2026 im aktuellen Format weiterhin geben. FÃ¼r jeden Zug,\n\nder in einer ZvF geregelt ist, wird es eine BauFplo geben. Ab EinfÃ¼hrung von Annex7, wird es",238,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":28,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","29c332f9a585c156cf3df2bb79f5b0e816519677a11ee576244780e28e62f74b"],["chunk_00089717cb7787b9f81df562","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",51,"Seite 28","keine ZvFen mehr geben, sondern GPE (Grobplanungsergebnis) und FPE (Feinplanungsergebnis) - diese sind auch zugbezogen. Sobald es ein FPE gibt, gibt es dann auch eine BauFplo.\n\n1.13 Wird die ZvF noch auf der MaÃŸnahmenebene geregelt oder gibt es auch eine Zvf pro\n\nZug/Tag?\n\nZvFen wird es auch im Fahrplanjahr 2026 im aktuellen Format weiterhin geben. FÃ¼r jeden Zug,\n\nder in einer ZvF geregelt ist, wird es eine BauFplo geben. Ab EinfÃ¼hrung von Annex7, wird es\n\nkeine ZvFen mehr geben, sondern GPE (Grobplanungsergebnis) und FPE (Feinplanungsergebnis) - diese sind auch zugbezogen. Sobald es ein FPE gibt, gibt es dann auch eine BauFplo.\n\n1.14 Wie wird sich das ZvF-Verfahren Ã¤ndern? Wird ein ZvF auf Zugnummer und Datum\n\nbezogen sein oder weiterhin auf eine BaumaÃŸnahmenummer?\n\nAb dem Fahrplanjahr 2027 wird es aufgrund des Annex VII keine ZvF fÃ¼r eine BaumaÃŸnahme\n\nmit allen betroffenen ZÃ¼gen geben, sondern pro Zug, der durch die BaumaÃŸnahme fÃ¤hrt, ein\n\nGPE und ein FPE.\n\n1.15 Worin unterscheiden sich die Inhalte einer BauFplo und einem Feinplanungs Ergebnis (FPE)?\n\nDas FPE enthÃ¤lt die trassenbezogene Sicht eines baubetroffenen Zuges. Der Unterschied ist,\n\ndass die digitale BauFplo ein betriebliches Dokument ist und Informationen enthÃ¤lt, die nicht auf\n\ndem FPE sind.\n\n1.16 Wird es ZeitsprÃ¼nge geben innerhalb eines Fahrplanes? (Teilausregelung)\n\nMit der EinfÃ¼hrung von TAF/TAP-TSI und gemÃ¤ÃŸ Richtlinie 402.0305 der INB 2027 (Annex VII\n\nProzess) wird es keine rÃ¤umlichen Inkonsistenzen mehr geben und somit wÃ¼rden sie auch nicht\n\nin der BauFplo sichtbar sein. Zeitliche Inkonsistenzen (positive und negative ZeitsprÃ¼nge) kÃ¶nnen wir bei Teilausregelungen aktuell leider nicht ausschlieÃŸen und weisen diese am Laufweg\n\nauf der BauFplo aus. An dieser Thematik arbeiten wir weiterhin.",268,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":28,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","748a0af96ff2dec5a35642469109060fbf2f5470b0db417d53aa5892d502146e"],["chunk_a036e7019735f413b6e826d6","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",52,"Seite 28","V.IWF 41 Fragenkatalog 28",4,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":28,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","33f361b5ea7d38e1745739decfe4fe199061d6c1588e0dd051f93a12dfeac125"],["chunk_ba7528bed2db767f07863b7f","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",53,"Seite 29","1.17 Muss weiterhin das Excel-Formular fÃ¼r baubedingte Zusatzleistungen ausgefÃ¼llt\n\nwerden oder erfolgt das zukÃ¼nftig auch Ã¼ber ein digitales Tool?\n\nBis zur EinfÃ¼hrung von TAF/TAP-TSI muss weiterhin via Excel-Liste bestellt werden.\n\n1.18 Mit der Herausgabe tagesscharf, das dann sicherlich auch EBula, werden wir arbeiten kÃ¶nnen. Ich prÃ¼fe ja auch den Regelfahrplan nicht jeden Tag. Wie sehe ich aber, dass\n\ndie BaumaÃŸnahme korrekt verarbeitet wurde. Denn dafÃ¼r mÃ¼sste es ja sowas wie ein Angebot geben (ggf. auch tabellarisch).\n\nDer Prozess fÃ¼r die Abstimmung und Konsultation von BaumaÃŸnahmen findet sich in der Richtlinie 402.0305 (Umsetzung Annex VII Prozess).\n\nWeitere Informationen finden Sie auf folgender Internetseite:\n\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\n\n1.19 Was bedeutet der Zeitraum z-3? Bedeutet dies, dass ein EVU erst drei Tage vor der\n\nentsprechenden netzbedingten EinschrÃ¤nkung Ã¼ber diese EinschrÃ¤nkung informiert\n\nwird? Oder bedeutet dies, dass erst drei Tage vor der EinschrÃ¤nkung ein Fahrplan versendet wird? Oder handelt es sich hier nicht um Tage, sondern um Monate?\n\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte VerfÃ¼gbarkeitseinschrÃ¤nkungen an die EVU kommuniziert werden mÃ¼ssen. Wie weit im\n\nVoraus eine VerfÃ¼gbarkeitseinschrÃ¤nkung kommuniziert werden muss, hÃ¤ngt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heiÃŸt\n\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\n\nWeitere Informationen finden Sie auf folgender Internetseite:\n\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512",217,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":29,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","d198482f7348da06112f3237bbb2ff7a7d3572fcfa15e87bc1e852f27cf7b662"],["chunk_1741d97e61e7f077ea620fa1","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",54,"Seite 29","1.20 Wie ist das Zusammenspiel und die Ãœbermittlung der BauFplo-Fahrplaninformationen Ã¼ber die anderen Fahrplanschnittstellen der DB InfraGo (NSS mit GFD und BZD und\n\nzukÃ¼nftig TAF/TAP TSI) vorgesehen? â€“ Sind weiterhin Konstellationen mÃ¶glich, wo Informationen zum nicht mehr gÃ¼ltigen Regelfahrplan erst nach der Ã¼bermittelten BauFplo bei\n\nuns eintreffen?\n\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) sieht eine vorgegebene Reihenfolge\n\nder VerÃ¶ffentlichung von Fahrplandokumenten vor, die den Regelprozess darstellt.\n\nWeitere Informationen finden Sie auf folgender Internetseite:\n\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\n\n1.21 Was genau wird unter einer netzausgelÃ¶sten Ã„nderung verstanden? Worin besteht\n\nder Unterschied zu einer BauFplo? In welchem Format erhalten wir die NAÃ„?\n\nIn Abschnitt 8 Absatz 6 der Richtlinie 402.0305 der INB 2027 sind Regelungen zur BauFplo und\n\nnetzausgelÃ¶sten Ã„nderung (NAÃ„) enthalten. Mit der NÃ„A werden die vertragsrelevanten Vorgaben aus der FPE umgesetzt, deswegen lÃ¶st die DB InfraGO AG mit der Bereitstellung des FPE\n\nzeitgleich die NAÃ„ aus. Im Gegensatz dazu ist die BauFplo ein betriebliches Informationsdokument. Sie informiert die TriebfahrzeugfÃ¼hrenden und den Betrieb Ã¼ber alle baubedingten Auswirkungen auf den Zuglauf. Die NAÃ„ wird Ã¼ber das TPN an das EVU Ã¼bermittelt. Die BauFplo\n\nkann im digitalen Datenformat (XML, JSON) Ã¼ber eine Schnittstelle abgerufen werden, wird\n\naber gleichzeitig auch noch als PDF-Format per E-Mail versendet.\n\nV.IWF 41 Fragenkatalog 29",204,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":29,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","22fa0c5a0659341d4ff04f76489b05214f6e9f55d864ba6da9a578569d95e10b"],["chunk_d3e40063b9ca7d9bb69a5a5e","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",55,"Seite 30","1.22 Damit RNE eindeutige IST-Zeiten liefern kann, bedarf es einer Ãœbereinstimmung der\n\ngelieferten und der gefahrenen OrtsverlÃ¤ufe. Werden Informationen zu Fahrzeiten und\n\nOrtsverlÃ¤ufen aus der BauFplo auch in der Datenlieferung an die RNE enthalten sein und\n\ndamit im RNE TIS abrufbar?\n\nAuf der BauFplo wird es zum aktuellen Kenntnisstand keine TAF/TAP-TSI-Identifier geben, da\n\ndie Spezifikation zu TAF/TAP-TSI keine Vorgaben zur BauFplo macht.\n\n1.23 Wie wird sichergestellt, dass alle Verkehre einen Fahrplan bekommt, wo heute nur\n\nmit Trickserei (keine konfliktfreie Planung oder weiter +XX) Ã¼berhaupt was mÃ¶glich ist?\n\nDer Prozess fÃ¼r die Abstimmung und Konsultation von BaumaÃŸnahmen findet sich in der Richtlinie 402.0305 (Umsetzung Annex VII Prozess).\n\nWeitere Informationen finden Sie auf folgender Internetseite:\n\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\n\n1.24 Gibt es eine \"deadline\", ab wann es keine Ã„nderungen zur Fplo mehr gibt bzw geben\n\ndarf?\n\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte VerfÃ¼gbarkeitseinschrÃ¤nkungen an die EVU kommuniziert werden mÃ¼ssen. Wie weit im\n\nVoraus eine VerfÃ¼gbarkeitseinschrÃ¤nkung kommuniziert werden muss, hÃ¤ngt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heiÃŸt\n\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\n\nWeitere Informationen finden Sie auf folgender Internetseite:\n\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\n\n1.25 Wenn mehrere BaumaÃŸnahmen in unterschiedlichen Regionen durchfahren werden,\n\nist die zeitliche Konsistenz sichergestellt?",210,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":30,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","df0054a051638913be990a4b980215fcf09daedae44866ebdaaf896f0f44802e"],["chunk_1ca63ab825ba659f211407b0","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",56,"Seite 30","Mit der EinfÃ¼hrung von TAF/TAP-TSI und gemÃ¤ÃŸ der Richtlinie 402.0305 der INB 2027 (Umsetzung Annex VII Prozess) wird es im FPE keine rÃ¤umlichen Inkonsistenzen mehr geben und somit wÃ¼rden sie auch nicht in der BauFplo sichtbar sein. Zeitliche Inkonsistenzen kÃ¶nnen wir aktuell leider nicht ausschlieÃŸen. An dieser Thematik arbeiten wir weiterhin.\n\n1.26 Mit welchem Vorlauf wird die digitale BauFplo versendet?\n\nDie Richtlinie 402.0305 (Umsetzung Annex VII Prozess) definiert Zeitpunkte, an denen sogenannte VerfÃ¼gbarkeitseinschrÃ¤nkungen an die EVU kommuniziert werden mÃ¼ssen. Wie weit im\n\nVoraus eine VerfÃ¼gbarkeitseinschrÃ¤nkung kommuniziert werden muss, hÃ¤ngt von verschiedenen Faktoren ab. Das \"z\" bedeutet immer \"Wochen vor Baubeginn\". Das bedeutet, \"z-3\" heiÃŸt\n\n\"3 Wochen vor Baubeginn\" wird der Zug am Verkehrstag mittels digitaler Baufplo versendet.\n\nWeitere Informationen finden Sie auf folgender Internetseite:\n\nhttps://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34eu-11857512\n\n1.27 Identifikatoren fÃ¼r Betriebsstellen im Zuglauf: Alle Datenelemente, die eine Betriebsstelle referenzieren (z.B. /content/fahrplan/laufwegÃ¤nderung/betriebsstelle), verwenden in\n\nder digitale BauFplo weiterhin den herkÃ¶mmlichen RL100-Code zur Identifikation der Betriebsstelle. KÃ¼nftig mit TAF/TAP TSI werden jedoch die PrimaryLocationCodes (PLC) der\n\nfÃ¼hrende und alleinige Identifikator fÃ¼r Betriebsstellen sein. Beabsichtigen Sie, die digitale BauFplo auf die PLC-Systematik umzustellen (spÃ¤testens mit EinfÃ¼hrung von TTT im\n\nBereich Fahrplan der DB InfraGO ab JFpl 2027)? Hinweis: Die Verwendung von PLC/SLC\n\nV.IWF 41 Fragenkatalog 30",201,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":30,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","8d1d3b4e945742dd82973dfbaf896381a926b8aca0dedcc9b99642e23b52e562"],["chunk_a3aaf0d3580e4b0f534111bb","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",57,"Seite 31","zur Identifikation von Betriebsstellen ist ein europÃ¤ischer Standard/Vorgabe gemÃ¤ÃŸ\n\nTAF/TAP TSI.\n\nWir werden auch die VerÃ¶ffentlichungsdokumente, wie die BauFplo, in einen TAF/TAP-TSI-konformen Zustand Ã¼berfÃ¼hren. Allerdings werden weiterhin RL 100-Codes fÃ¼r die Betriebsstellen\n\nangezeigt.\n\n1.28 Datentypen und Validierungen: Sie verwenden vielfach den Datentyp â€žStringâ€œ fÃ¼r Attribute, die eigentlich eine wohlbekannte Wertemenge darstellen und deshalb nach Stand\n\nder Technik als Enumeration definiert werden sollten â€“ Beispiel: Bremsstellung â€“ oder\n\nfÃ¼r die man auf andere Art eine EinschrÃ¤nkung der erlaubten Wertemenge vornehmen\n\nsollte â€“ Beispiel: statt die KV-Profile einfach nur als â€žStringâ€œ zu definieren wÃ¤re der Stand\n\nder Technik, auf diesem String eine EinschrÃ¤nkung wie <pattern value=\"\\d{3}\"/> zu definieren. Aus meiner Sicht entspricht die aktuelle Vorgabe nicht dem Stand der Technik,\n\nund die wesentlichen Vorgaben hÃ¤tten leicht aus dem TAF/TAP TSI-Standard Ã¼bernommen werden kÃ¶nnen.\n\nUm die Schnittstelle flexibel nutzbar zu halten, wurde zunÃ¤chst auf generische Typen gesetzt.\n\nZudem ist die BauFplo nicht unmittelbar an den TAF/TAP-TSI-Standard gebunden, da es sich\n\num Dokumente fÃ¼r die DurchfÃ¼hrung der Zugfahrt handelt, deren EinfÃ¼hrung zeitlich versetzt zu\n\nden TAF/TAP-TSI-Vorgaben erfolgt.\n\n1.29 Zugnummer, OTN und TrainID: Sie verwenden die generische Bezeichnung â€žZugnummerâ€œ (z.B. /content/zug/nummer). Ist damit gemeint:\n\n- die â€žklassischeâ€œ Zugnummer heutiger PrÃ¤gung gemeint\n\n- die betriebliche Zugnummer nach TAF/TAP TSI Standard, die sog. OTN\n\n- die planerische Zugnummer nach TAF/TAP TSI Standard, die sog. TrainID\n\n(jetzt und auch nach EinfÃ¼hrung von TAF/TAP TSI in Fahrplan und Betrieb ab JFpl 2027)",233,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":31,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","d4ff5caf5b14e5cdbc749de9c42477ff4074d7ae552770d629410a68fdbf333f"],["chunk_9e842a151581e42bc7f58f05","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",58,"Seite 31","Mit â€žZugnummerâ€œ ist im Kontext der BauFplo die betriebliche Zugnummer (OTN) nach TAF/TAP\n\nTSI gemeint.\n\n1.30 Technische Abstimmung mit \"Fahrplan\" und \"Betrieb\" bei DB InfraGO\n\nGibt es an irgendeiner andere Stelle Abstimmungen mit den Datenformaten und den Datenstrukturen, die die TAF/TAP TSI kompatiblen Systeme der DB InfraGO verwenden (PathOS, BDV Betriebsdatenverteiler, etc.)?\n\nMein erster Eindruck ist, dass das Format der â€ždigitalen BauFploâ€œ von diesen Standards\n\nkomplett losgelÃ¶st definiert ist.\n\nFÃ¼r Mitte 2026 ist vorgesehen, die VerÃ¶ffentlichungsdokumente â€“ einschlieÃŸlich der BauFplo â€“\n\nin einen TAF/TAP TSI-konformen Zustand zu Ã¼berfÃ¼hren.\n\nAktuell ist die BauFplo noch losgelÃ¶st von den TAF/TAP TSI-Strukturen, da diese Vorgaben\n\nsich nicht auf die Fahrplandokumente beziehen.\n\n1.31 Frage zur EinfÃ¼hrung der digitalen FPLO: Mein VerstÃ¤ndnis ist, das mit der EinfÃ¼hrung TAP-TSI / Annex VII zum Fahrplan 2027 komplett auf die digitale FPLO umgestellt\n\nwird. Meine Frage bezieht sich auf den EinfÃ¼hrungspfad: Was bedeutet das fÃ¼r den Hochlauf ab ca. 08/26? Werden alle Dokumente, die sich auf den Fpl 2027 beziehen automatisch im neuen Format versendet? Dokumente mit Bezug bis zum Datum des Fpl-Wechsels (also noch der komplette Fahrplan 2026) werden Ã¼ber den alten Weg und Formate\n\nkommuniziert?\n\nV.IWF 41 Fragenkatalog 31",192,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":31,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","7289de6c3fd3c33eef8fed959e1b6d176b533a7ec11d11b4e5ac23b9599aaa7d"],["chunk_3fe2a12ecfbd0b424040fa4f","wiki/sources/260731-fragenkatalog-annex-vii-4-kp-data.md",59,"Seite 32","Wird eine Bautrasse nach Richtlinie 402.0305 (Umsetzung Annex VII Prozess) konsultiert und\n\nmit einem GPE, FPE und NAÃ„ verÃ¶ffentlicht, wird es nur im neuen Format mÃ¶glich sein die\n\nBauFplo zu versenden. Ab Oktober 2026 muss mit dem Format gerechnet werden.\n\n1.32 Inwiefern ist die EinfÃ¼hrung der digitalen BauFplo mit der EinfÃ¼hrung von Taf/Tap\n\nTSI zusammenhÃ¤ngend? Welche technischen GrÃ¼nde liegen fÃ¼r einen Zusammenhang\n\nder EinfÃ¼hrung von Taf/Tap TSI und der digitalen BauFplo vor?\n\nGenerell ist die EinfÃ¼hrung der digitalen BauFplo nicht von TAF/TAP-TSI abhÃ¤ngig. Die DVO\n\n2017/2075 (Umsetzung Annex VII Prozess) schreibt aber einen Zugbezug vor. Mit dem FPE\n\nund GPE verÃ¶ffentlichen wir zugbezogen, daher brauchen wir aber auch eine neue Form der\n\nBauFplo.\n\n1.33 Wir schreiben das Fahrplanjahr 2027. TTT ist erfolgreich eingefÃ¼hrt. Dann erhalten\n\nwir fÃ¼r jede VerÃ¤nderung an der Trasse, egal mit welchem Vorlauf immer eine PDM durch\n\nInfraGO mit dem letzten gÃ¼ltigen laufweg und Zeiten. Wird dann fÃ¼r jede dieser Versionen\n\nauch immer automatisch ein Dokument in BSV angestoÃŸen?\n\nWenn es nach der Richtlinie 402.0305 der INB 2027 (Umsetzung Annex VII Prozess) ein FPE\n\nund ein NAÃ„ gibt, dann gibt es auch eine BauFplo aus BSV. Zu einer anderen PDM, die es aus\n\nanderen Fahrplanphasen oder vom Betrieb geben kann, wird es keine BauFplo aus BSV geben.\n\n1.34 Wenn ein Zuglauf unterbrochen wird, z.B. Zug 18412 verkehrt nicht von A bis Z sondern nur von A bis B, dann Ausfall und dann wieder von X bis Z. Der ''hintere'' Zug\n\nbraucht eine neue Zugnummer. Die wird von InfraGO vergeben und nicht von mir als\n\nEVU. Erkennt man den Zusammenhang zwischen diesen ZÃ¼gen?\n\nIn der digitalen BauFplo ist in diesem Fall kein Bezug bei der Trasse mit der neuen Zugnummer",282,"{\"canonical_url\":null,\"normalized_sha256\":\"81468c75504d4b21e9addf1c41aa4d017f1019ee1fb3412ab8c7d2e8aac99092\",\"page\":32,\"source_id\":\"src_8d6f50ab68ebe282b0bf\",\"source_sha256\":\"07cbda3ba66f907b6bbf045f8e8c23f8a72882e2ba6310b39c34eb6ed7792fe3\",\"source_version_id\":\"sv_d1f533b4f6522338407b5115\"}","f61b33b10d3f6b89e3799ff1fb337f0692b4ac2b9c72fc25000b0ba70d524115"]]');
