INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_3dd1a93e48eff3f1216fa390","wiki/sources/annex-vii-der-neue-prozess-zur-baukommunikation.md",6,"Der Annex VII unterscheidet vier Konsultationsphasen:","3\\. Konsultationsphase: x-12 Monate bis x-4 Monate\n\n- Prozessphase: Mehrjahresplanung\n- Bearbeitung aller BaumaÃŸnahmen bis sieben Tage Dauer, die nicht im Netzfahrplan abgebildet sind.\n- Bearbeitung parallel zur Erstellung Netzfahrplan.\n- Weiterhin Teil 1 (1. Quartal) und Teil 2 (2. bis 4. Quartal) prozessual erforderlich.\n- Koordinationszeitraum: x-12 bis x-4\n- Konsultationszeitpunkt: Die Konsultation erfolgt in 2 Teilen: Zu x-8,75 fÃ¼r Teil 1 (1. Quartal des Fahrplanjahres) und zu x-6,5 fÃ¼r Teil 2 (2. bis 4. Quartal des Fahrplanjahres).\n- BKE-Kategorien: 5, 3 und 2\n- BAE-Kategorien: BAE B (kleiner 7 Tage)\n- Objekt der SN: BKE mit BBR und BAE mit bVE\n- AblÃ¶sung: KiGbau (Kundeninformation GroÃŸbaumaÃŸnahmen)\n- Entwicklungsstand in der KOMBau: Konsultationen der 3. KP werden in der KOMBau durchgefÃ¼hrt.\n- Betroffenheit Serviceeinrichtung und Infrastrukturanschluss: Die Integration in der KOMBau mit dem Ziel einer harmonisierten Darstellung von Trasse, Serviceeinrichtung und Infrastrukturanschluss, ist erfolgt.\n\n4\\. Konsultationsphase: unterjÃ¤hrig (fortlaufend ab x-4 bis Verkehrstag)",153,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34-eu-11857512\",\"normalized_sha256\":\"44c8516d86182905ff62c54535b703abced6827706a6eef4b9c1a67c5251708e\",\"page\":null,\"source_id\":\"src_d9c6bbffdd7e472ffb34\",\"source_sha256\":\"315599ecffe51fadee3528f9bc7a919c7b89be0a44161ccf8840bb02fc9e7164\",\"source_version_id\":\"sv_69e507ac27f399de23ebcd36\"}","94c9d02061ea3fcd82e81e07c860e3ea13a6d0713c03b1b7ae12a46a6cae6458"],["chunk_d7e8831fa38bf4c600eacf35","wiki/sources/annex-vii-der-neue-prozess-zur-baukommunikation.md",7,"Der Annex VII unterscheidet vier Konsultationsphasen:","- Prozessphase: UnterjÃ¤hrige Planung\n- Ausdetaillierung aller BaumaÃŸnahmen, die keine BerÃ¼cksichtigung im Netzfahrplan finden.\n- Start-Ziel-Konstruktion der Trassen mit Beachtung aller Baustellen auf Gesamtlaufweg.\n- Im Zielprozess ErhÃ¶hung der Trassenkonsistenzen mittels neuer Fahrplanprodukte.\n- Konsultationszeitpunkt: z-24 (z = Wochen vor Baubeginn/Verkehrstag)\n- BKE-Kategorien: 1\n- BAE-Kategorien: BAE A und BAE B\n- Objekt der SN: Grobplanungsergebnis einer baubetroffenen Trasse\n- AblÃ¶sung: Zusammenstellung vertrieblicher Folgen (ZvF), Ãœbergabeblatt (ÃœB)\n- Entwicklungsstand in der KOMBau: EinfÃ¼hrung im Q2 des Kalenderjahres 2026 geplant\n- Betroffenheit Serviceeinrichtung und Infrastrukturanschluss: Die Integration in der KOMBau mit dem Ziel einer harmonisierten Darstellung von Trasse, Serviceeinrichtung und Infrastrukturanschluss, ist voraussichtlich fÃ¼r das Fahrplanjahr 2027 eingeplant.\n\n[Informationsveranstaltung â€žVertiefung ujBau\" vom 27.11.2025 (PDF | 2,7 MB)](https://www.dbinfrago.com/resource/blob/13641032/779d507eed0b81d6c024376a84477d0b/Informationsveranstaltung-Vertiefung-ujBau-vom-27-11-2025-data.pdf \"Es wird eine Datei heruntergeladen\")\n\n[Informationsveranstaltung â€žVertiefung ujBauâ€œ am 27.03.2026 (PDF | 1,6 MB)](https://www.dbinfrago.com/resource/blob/13794138/a8bb0b1c748de0d85e1490f013bb4c4f/Informationsveranstaltung-Vertiefung-ujBau-vom-27-03-2026-data.pdf \"Wird in einem neuen Tab geÃ¶ffnet\")\n\n[Informationsveranstaltung â€žVertiefung ujBauâ€œ am 20. Mai 2026 (PDF | 1,4 MB)](https://www.dbinfrago.com/resource/blob/13882916/c3bffb706af4d186eb026acafae04597/Informationsveranstaltung-Vertiefung-ujBau-vom-20-05-2026-data.pdf \"Wird in einem neuen Tab geÃ¶ffnet\")",153,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/fahren_und_bauen/annex-vii-richtlinie-2012-34-eu-11857512\",\"normalized_sha256\":\"44c8516d86182905ff62c54535b703abced6827706a6eef4b9c1a67c5251708e\",\"page\":null,\"source_id\":\"src_d9c6bbffdd7e472ffb34\",\"source_sha256\":\"315599ecffe51fadee3528f9bc7a919c7b89be0a44161ccf8840bb02fc9e7164\",\"source_version_id\":\"sv_69e507ac27f399de23ebcd36\"}","349eb9c66397f2d0dbc0b0f31fb6947205cdf6689490481735ea4374be7b95a7"],["chunk_42323845cfc985cf96fd0c5d","wiki/sources/annex-vii-der-neue-prozess-zur-baukommunikation.md",8,"Der Annex VII unterscheidet vier Konsultationsphasen:","[Informationsveranstaltung â€žVertiefung ujBauâ€œ am 25. Juni 2026 (PDF | 1,5 MB)](https://www.dbinfrago.com/resource/blob/13956534/6b13eddc509dc54eb5d5fa6cffb64c26/Informationsveranstaltung-Vertiefung-ujBau-vom-25-06-2026-data.pdf \"Wird in einem neuen Tab geÃ¶ffnet\")\n\n[Informationsveranstaltung â€žVertiefung ujBauâ€œ am 31. Juli 2026 (PDF | 1,4 MB)](https://www.dbinfrago.com/resource/blob/13988518/36ac58595204c5a6a5e2cfffe5f065be/Informationsveranstaltung-Vertiefung-ujBau-vom-31-07-2026-data.pdf \"Wird in einem neuen Tab geÃ¶ffnet\")\n\nRichtline 402.0305 â€“ Terminkalender fÃ¼r 2026[JÃ¤hrlicher Terminkalender 2026\\_Ril. 402.0305, Terminkette 2026 (3. Nachtrag)](https://www.dbinfrago.com/resource/blob/13619388/7ef564dc200bb895dde1d1e67441c6ec/Jaehrlicher-Terminkalender-2026_Ril-402-0305-Terminkette-2026-1-Nachtrag--data.pdf \"Es wird eine Datei heruntergeladen\")\n\n[\n\nPDF | 148,8 KB\n\n](https://www.dbinfrago.com/resource/blob/13619388/7ef564dc200bb895dde1d1e67441c6ec/Jaehrlicher-Terminkalender-2026_Ril-402-0305-Terminkette-2026-1-Nachtrag--data.pdf \"Es wird eine Datei heruntergeladen\")[â€¢ JahresÃ¼berblick Kalenderjahr 2026 mit MÃ¶glichkeiten zur Stellungnahme (SN) (3. Nachtrag)](https://www.dbinfrago.com/resource/blob/13619386/36278523d09d6e17bf342acb6d4ecc27/Jahresueberblick-Kalenderjahr-2026-mit-Moeglich