INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_df4e0e8761236ea1be27ddcc","wiki/sources/faq-rv-29-stand-maerz26-data.md",5,"Seite 5","FAQ zu RV-Konzept 2029\n\nBestellgrundlage: Verkehrstageregelung\n\nï± Kann auf Wunsch eine spezifische Verkehrstageregelung (z.B. VT nur Fr oder Di/Do) fÃ¼r RahmenvertrÃ¤ge zugelassen werden?\n\nBei den zulÃ¤ssigen Verkehrstageregelungen hat sich die DB InfraGO an den am hÃ¤ufigsten vorkommenden VerkehrstageschlÃ¼sseln orientiert. Der Abschluss von\n\nRahmenvertrÃ¤gen fÃ¼r Einzeltage wird nicht unterstÃ¼tzt, da dies einer optimalen Netznutzung entgegenwirken wÃ¼rde. FÃ¼r Einzellagen an wenigen Verkehrstagen, VerstÃ¤rkerund Sonderverkehre steht KapazitÃ¤t im Netzfahrplan oder im Gelegenheitsverkehr zur VerfÃ¼gung. Wir prÃ¼fen jedoch die vorgebrachten VorschlÃ¤ge, beispielsweise fÃ¼r den\n\nVT Freitag in der weiteren Konzepterstellung in AbwÃ¤gung mit der KapazitÃ¤tsoptimierung.\n\nï± KÃ¶nnen innerhalb der Verkehrstagereglung spezielle ZeitrÃ¤ume unterschieden werden (z.B. Fr. 12-16 Uhr) ?\n\nEine Differenzierung innerhalb von Verkehrstagen ist leider nicht mÃ¶glich, da die Optimierung der KapazitÃ¤t Ã¼ber alle Verkehrsarten dann nicht mÃ¶glich ist.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n5",137,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":5,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","30d3436b305b89070783f346da129f1fe0ea708e84ad73659a29d64f288f4163"],["chunk_5c03200bf19eca3f12420789","wiki/sources/faq-rv-29-stand-maerz26-data.md",6,"Seite 6","FAQ zu RV-Konzept 2029\n\nBestellgrundlage: KapazitÃ¤tsabschnitte\n\nï± Welches IT-Tool ist fÃ¼r die Anmeldung von RV 2029 vorgesehen ?\n\nEs wird ein neues IT-Bestellsystem zur VerfÃ¼gung gestellt, Ã¼ber das RV-Anmeldungen und RV-Angebote abgewickelt werden sowie zusÃ¤tzlich ein IT-Tool fÃ¼r die\n\nKonfliktdetektion und â€“bearbeitung inkl. der Dokumentation der Konfliktentscheidungen gegenÃ¼ber der BNetzA.\n\nï± Wie soll die RV-Anmeldung fÃ¼r lange Laufwege mit geflÃ¼gelten Teilabschnitten erfolgen ?\n\nBei der RV-Anmeldung wird der gesamte Laufweg des Stamms angegeben werden. Der FlÃ¼gel ist dann eine separate RV-Anmeldung.\n\nï± Wie wird das Stundenfenster ausgewÃ¤hlt?\n\nBei der RV-Anmeldung mÃ¼ssen fÃ¼r jeden KapazitÃ¤tsabschnitt eine gewÃ¼nschte Abfahrtszeit am Beginn und eine gewÃ¼nschte Ankunftszeit am Ende angegeben werden.\n\nDaraus ergibt sich automatisch, in welchem Zweistundenzeitfenster der KapazitÃ¤tsabschnitt gezÃ¤hlt wird.\n\nï± Wie wird mit neuer Infrastruktur (z.B. Inbetriebnahmen) im Zeitraum zwischen 2029 und 2033 umgegangen ?\n\nIm RV-Zeitraum Fahrplanjahr 2029-2033 sind keine grÃ¶ÃŸeren Infrastrukturinbetriebnahmen vorgesehen. Kleinere und erst spÃ¤ter relevante InfrastrukturverÃ¤nderungen\n\nkÃ¶nnen Ã¼ber den jÃ¤hrlichen Umwandlungsprozess fÃ¼r die RV-Bezugslinien berÃ¼cksichtigt werden.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n6",170,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":6,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","313cbbe51e0d096e991cca41a03c2766fd2e50f9a8613231aa8d61a5a03e8df1"],["chunk_0fddbe7980aa73ff5a7df005","wiki/sources/faq-rv-29-stand-maerz26-data.md",7,"Seite 7","FAQ zu RV-Konzept 2029\n\nBestellgrundlage: AnschlÃ¼sse/ Umlauf\n\nï± Wie kÃ¶nnen AnschlÃ¼sse bei der RV-Vergabe gewÃ¤hrleistet werden ?\n\nBei der RV-Vergabe werden zunÃ¤chst keine AnschlÃ¼sse berÃ¼cksichtigt, dies erfolgt dann bei der Umwandlung in die RV-Bezugslinie und der Trassenanmeldung\n\nzum jeweiligen Netzfahrplan.\n\nï± Wie kÃ¶nnen AnschlÃ¼sse in der RV-Bezugslinie berÃ¼cksichtigt werden ?\n\nAnschlÃ¼sse werden bei der jÃ¤hrlichen Umwandlung in eine konkrete RV-Bezugslinie seitens des ZB angegeben und werden bestmÃ¶glich berÃ¼cksichtigt.\n\nï± Wie hoch ist die FlexibilitÃ¤t bei der Umwandlung in eine RV-Bezugslinie ?\n\nDie RV-Bezugslinie muss einerseits in dem jeweiligen Zweistundenzeitfenster liegen, andererseits mÃ¼ssen die jeweiligen Mindest- und Maximalfahrzeiten\n\neingehalten werden. NÃ¤here Details werden in den INB 2027 geregelt werden.\n\nï± DÃ¼rfen ZB vom RV zurÃ¼cktreten, wenn der Umlauf nicht gesichert ist ?\n\nDie RV-Bezugslinie wird ohne Zustimmung des ZB nicht auÃŸerhalb des zulÃ¤ssigen Spielraums festgelegt, so dass hierdurch das Risiko minimiert ist, dass\n\nein Umlauf nicht zustande kommen kann. Daher ist ein separates RÃ¼cktrittsrecht bisher nicht vorgesehen.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n7",167,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":7,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","f35594aea3ed56bc7db26f30ee1914e75b3912f1e58764396907c24dfb1dadc8"],["chunk_25e8157ffa135d6b57dd0c70","wiki/sources/faq-rv-29-stand-maerz26-data.md",8,"Seite 8","FAQ zu RV-Konzept 2029\n\nZusÃ¤tzliche Bestellangaben (v.a. prognostizierte Fahrgastanzahl)\n\nï± Weshalb muss die Angabe der erwarteten Fahrgastanzahl erfolgen ?\n\nDie Angabe ist erforderlich, um auf dieser Basis innerhalb der Verkehrsart SPFV und SPNV eine Vergabeentscheidung zwischen konkurrierenden RV-Anmeldungen\n\ninnerhalb der Mindestmengen treffen zu kÃ¶nnen.\n\nï± Wo mÃ¼ssen die erwarteten Fahrgastzahlen angegeben werden ?\n\nDiese Angaben mÃ¼ssen bei RV-Anmeldung hinterlegt werden.\n\nï± Welche Angabe soll ein neuer Anbieter machen, der seine Fahrgastzahlen noch gar nicht kennt und wird diese Angabe vertraulich behandelt ?\n\nDie Angabe bezieht sich sowohl fÃ¼r etablierte als auch neue Anbieter auf die jeweilige eigene EinschÃ¤tzung. Die DB InfraGO wird die GeschÃ¤ftsgeheimnisse schÃ¼tzen\n\nund gewÃ¤hrleisten.\n\nï± Wie werden Passagierzahlen Ã¼ber die RV-Laufzeit (ggf. bis 15 Jahre) nachgehalten?\n\nWir appellieren auf die Angabe plausibler Werte, damit sich nicht einzelne Zugangsberechtigte einen unzulÃ¤ssigen Vorteil verschaffen. Sollten im Nachhinein\n\nunplausible oder deutlich Ã¼berzeichnete Werte erkennbar sein, kÃ¶nnen Ã¼ber entsprechende Regelungen in dem Nutzungsbedingungen Nachteile fÃ¼r den ZB\n\nentstehen, schlimmstenfalls auch RV-KapazitÃ¤ten durch die DB InfraGO AG gekÃ¼ndigt werden.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n8",178,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":8,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","e4ec9e06df19cd4ebc0d4a934c2413818940cfb5c273aad321779fdeb697e62b"],["chunk_94b6f180caa5dee865df446f","wiki/sources/faq-rv-29-stand-maerz26-data.md",9,"Seite 9","FAQ zu RV-Konzept 2029\n\nZusÃ¤tzliche Bestellangaben (v.a. prognostizierte Fahrgastanzahl)\n\nï± Die Anzahl der Passagiere schwankt stark wÃ¤hrend des Zuglaufs â€“ wie anmelden ?\n\nDie Angabe soll jeweils bezogen auf einen KapazitÃ¤tsabschnitt erfolgen (ggf. auch ein geeigneter Mittelwert).\n\nï± Wie soll das kÃ¼nftige Fahrgastaufkommen prognostiziert werden ?\n\nDB InfraGO geht davon aus, dass seitens der EVU und ZB geeignete EinschÃ¤tzungen vorliegen.\n\nï± WÃ¤re es denkbar, dass die Rangfolge innerhalb der SPNV-Mindestmenge von den AufgabentrÃ¤gern festgelegt wird (so dass die Angabe der\n\nerwartbaren Fahrgastzahlen im SPNV nicht erforderlich wÃ¤re) ?\n\nEin entsprechender konkreter Vorschlag ist bereits Ã¼bermittelt worden und wird im Rahmen der weiteren Konzepterarbeitung geprÃ¼ft.\n\nï± Wie kann die Angabe der erwarteten Fahrgastanzahl Ã¼berprÃ¼ft werden ?\n\nDie Angabe kann vorab seitens der DB InfraGO AG nur eingeschrÃ¤nkt validiert werden. Sollten im Nachhinein unplausible oder deutlich Ã¼berzeichnete Werte erkennbar\n\nsein, kÃ¶nnen Ã¼ber entsprechende Regelungen in dem Nutzungsbedingungen Nachteile fÃ¼r den ZB entstehen, schlimmstenfalls auch RV-KapazitÃ¤ten durch die DB\n\nInfraGO AG gekÃ¼ndigt werden.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n9",171,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":9,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","339d0649db743b6da92b866a24b06d5da0db8ecf1550b75ae4940df6c803abc5"],["chunk_5ecef2c008b7fe89632c7f8d","wiki/sources/faq-rv-29-stand-maerz26-data.md",10,"Seite 10","FAQ zu RV-Konzept 2029\n\nKapazitÃ¤tsobergrenze\n\nï± Wie wird die Obergrenze festgelegt ?\n\nDie Obergrenze ist auf die KapazitÃ¤t der Infrastruktur bezogen und wird mit einer eisenbahnbetriebswissenschaftlichen Methode korrekt ermittelt.\n\nï± Warum wird auch auf reinen SPNV-Strecken die Obergrenze beschrÃ¤nkt ?\n\nAus der gesetzlichen Grundlage ergibt sich zwingend, dass nicht die gesamte KapazitÃ¤t durch RahmenvertrÃ¤ge gebunden werden darf.\n\nï± Reduzieren Laufwegalternativen die KapazitÃ¤t?\n\nIm Gegenteil â€“ die verfÃ¼gbaren und sinnvollen Laufwegalternativen erhÃ¶hen die FlexibilitÃ¤t und ermÃ¶glichen eine optimale KapazitÃ¤tsausnutzung.\n\nï± Wie wird Infrastrukturneu- und Ausbau bei der Obergrenze berÃ¼cksichtigt ?\n\nEs wird fÃ¼r die RV-Vergabe eine Planungsbasis fÃ¼r die Infrastruktur unterstellt. In den Fahrplanjahren 2029 bis 2033 sind keine grÃ¶ÃŸeren Infrastrukturinbetriebnahmen\n\nvorgesehen, die von Vornherein die Obergrenze stark beeinflussen. NachtrÃ¤gliche Optimierungen kÃ¶nnen jÃ¤hrlich Ã¼ber eine angepasste RV-Bezugslinie berÃ¼cksichtigt\n\nwerden.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n10",139,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":10,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","1881fcc179f517c7991c067aa8f235d4e1bd1271c287d91f80785546f6150dba"],["chunk_cc2adf1d08730a66880bcfda","wiki/sources/faq-rv-29-stand-maerz26-data.md",11,"Seite 11","FAQ zu RV-Konzept 2029\n\nVerkehrsartenspezifische Mindestmengen\n\nï± Wie wird die Mindestmenge pro Verkehrsart festgelegt ?\n\nDie Mindestmengen je Verkehrsart werden Ã¼ber einen Gutachter ermittelt und festgelegt.\n\nï± Wird die Methodik des Gutachters auch konsultiert ?\n\nDie Datengrundlage und die Ableitung der Mindestmengen werden dem Markt transparent dargestellt und kÃ¶nnen von der BNetzA Ã¼berprÃ¼ft werden.\n\nï± Wo gilt die Regel zur WettbewerbsfÃ¶rderung (Eigenbelegungsregel) ?\n\nDie Eigenbelegungsregel gilt in der Verkehrsart SPFV, fÃ¼r die Verkehrsart SGV haben wir bisher keinen Wunsch oder Bedarf nach speziellen eigenen Regelungen erhalten.\n\nï± Wie wird die Mindestmenge fÃ¼r eine Verkehrsart dimensioniert, wenn die RV-Obergrenze in den Infrastrukturabschnitten unterschiedlich hoch ist ?\n\nDie Mindestmenge je Verkehrsart wird auf Basis des Infrastrukturabschnitts vom Gutachter festgelegt. Die Zuweisung einer RV-KapazitÃ¤t fÃ¼r einen bestellten\n\nKapazitÃ¤tsabschnitt erfolgt dann, wenn sie auf allen zugrundeliegenden Infrastrukturabschnitten eine KapazitÃ¤t erhÃ¤lt.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n11",147,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":11,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","c6c3f0790dc649f72067536e34896cb6ed8a7662e58dd22f7c35c1e56cd48010"],["chunk_ab5ad73e9fd2cca90f7d6a3c","wiki/sources/faq-rv-29-stand-maerz26-data.md",12,"Seite 12","FAQ zu RV-Konzept 2029\n\nInternational\n\nï± Wird die RV-Vergabe grenzÃ¼berschreitend abgestimmt ?\n\nZur Netzfahrplanperiode 2029 gibt es nach unserem Kenntnisstand keine parallel laufende Vergabe von RahmenvertrÃ¤gen bei\n\nbenachbarten Infrastrukturbetreibern und auf Grenzstrecken zur DB InfraGO AG. Die internationale Koordinierung erfolgt dann bei der Umwandlung der RV-\n\nBezugslinie vor der jeweiligen Netzfahrplanperiode.\n\nï± Wie soll die RV-Bezugslinie mit den Nachbar-EIU abgestimmt werden ?\n\nDie grenzÃ¼berschreitende Harmonisierung erfolgt bei der Umwandlung der RV-KapazitÃ¤t in die RV-Bezugslinie; dies wird im Ã¼blichen Prozess der\n\nGrenzabstimmung vor der jeweiligen Netzfahrplanperiode stattfinden.\n\nï± Wie kann die Bezugslinie bei baubedingten Ã„nderungen mit den Nachbar-EIU harmonisiert werden (z.B. bei Ã„nderung des GrenzÃ¼bergangs in\n\nFolge einer Umleitung) ?\n\nVorÃ¼bergehende baubedingte Ã„nderungen werden ebenfalls bei der jÃ¤hrlichen Umwandlung in die konkrete RV-Bezugslinie berÃ¼cksichtigt und koordiniert.\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n12",136,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":12,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","1ab8e234be430e3e22ab83049dd36f2e7334f97cbef9346c637d9525095312fb"],["chunk_8d8f87c7ceff33ac36cb7ea9","wiki/sources/faq-rv-29-stand-maerz26-data.md",13,"Seite 13","FAQ zu RV-Konzept 2029\n\nZuweisungsverfahren RV-Vergabe\n\nï± Wie wird ein Konflikt zwischen zwei bzw. mehreren RV-Anmeldungen entschieden?\n\nWir betrachten alle RV-Anmeldungen auf einem Infrastrukturabschnitt Zweistundenzeitfenster. Wird die Obergrenze von 70 % Ã¼berschritten, erfolgt eine Koordinierung.\n\nBei gescheiterter Koordinierung wird Entscheidungsverfahren unter BerÃ¼cksichtigung der Mindestmengen pro Verkehrsart sowie darÃ¼ber hinaus gemeinsam Ã¼ber alle\n\nVerkehrsarten nach Regelentgelt entschieden. Ist eine eindeutige Entscheidung nicht mÃ¶glich, erfolgt das HÃ¶chstpreisverfahren.\n\nï± Wie werden SPNV-Taktverkehre bei der RV-Vergabe geschÃ¼tzt? Wird der SPNV durch das Regelentgeltverfahren benachteiligt?\n\nDurch die Mindestmengen pro Verkehrsart kÃ¶nnen die SPNV-Takte unabhÃ¤ngig vom jeweiligen Regelentgelt abgesichert werden. ZusÃ¤tzlich kÃ¶nnen in der verfÃ¼gbaren\n\nKapazitÃ¤t bis zur Obergrenze weitere SPNV-Takte auf Basis des Regelentgelts zugewiesen werden.\n\nï± Ist ein SPNV-Betreiberwechsel im RV zulÃ¤ssig?\n\nJa dies wird weiterhin mÃ¶glich sein.\n\nï± Wie wird das Regelentgelt berechnet?\n\nDas Regelentgelt berechnet sich fÃ¼r eine RV-Anmeldung Ã¼ber den gesamten bestellten Laufweg fÃ¼r alle Verkehrstage Ã¼ber die Dauer des Rahmenvertrags bis max. 5\n\nJahre (Dauer einer RV-Periode).\n\nï± Findet eine Teilzuweisung innerhalb von KapazitÃ¤tsabschnitten statt? Was passiert, wenn ein ZB z.B. nur den ersten und letzten KapazitÃ¤tsabschnitt\n\ndes angemeldeten Laufwegs erhÃ¤lt, aber das MittelstÃ¼ck nicht ?\n\nEs werden jeweils nur ganze KapazitÃ¤tsabschnitte zugewiesen. Der Fall der Zuweisung mit einer â€žLÃ¼ckeâ€œ bezogen auf den Gesamtlaufweg mit mehreren\n\nKapazitÃ¤tsabschnitten wird dem ZB eine Teilzuweisung automatisch angeboten und es kann angenommen oder sanktionsfrei nicht angenommen werden.",223,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":13,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","29b5f2bfde88172deb0df57f2b08729dad132978cd2e396cfc91bc8d9a65f903"],["chunk_51641d62e97ec43c35eb7848","wiki/sources/faq-rv-29-stand-maerz26-data.md",14,"Seite 13","DB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n13",11,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":13,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","2e741a71284b62619048f2c254f8d950b3459c1947548d7812a378343b49ba9d"],["chunk_851045873b9e03e0abe0c856","wiki/sources/faq-rv-29-stand-maerz26-data.md",15,"Seite 14","FAQ zu RV-Konzept 2029\n\nRV im Netzfahrplan\n\nï± Was passiert, wenn die im Rahmenvertrag unterstellte Infrastruktur nicht rechtzeitig realisiert wird oder wegen Bau oder fehlender internationaler\n\nHarmonisierung nicht zur VerfÃ¼gung steht ?\n\nEs wird zunÃ¤chst versucht, bei der jÃ¤hrlichen Umwandlung der RV-KapazitÃ¤t in eine RV-Bezugslinie fÃ¼r die konkrete Netzfahrplanperiode entsprechende Anpassungen\n\nvorzunehmen und eine tragfÃ¤hige LÃ¶sung zu finden. HierfÃ¼r gilt eine entsprechende Mitwirkungspflicht aller betroffenen ZB.\n\nï± Wie stark darf der RV-Inhaber von der RV-Bezugslinie abweichen und was passiert, wenn ZB sich bei der Trassenanmeldung zur NEP nicht an die RV-\n\nBezugslinie aus der Umwandlung halten ?\n\nDer zulÃ¤ssige Spielraum der Abweichung von der RV-Bezugslinie fÃ¼r die Trassenanmeldung wird noch im Detail festgelegt; wir werden uns hier an den bekannten\n\nWerten orientieren. HÃ¤lt sich der ZB nicht an die in der Umwandlung festgelegte RV-Bezugslinie bei der Trassenanmeldung im Netzfahrplan, entfÃ¤llt der\n\nrahmenvertragliche Schutz und der ZB erhÃ¤lt keinen Vorrang im Entscheidungsverfahren nach einem gescheiterten Koordinierungsverfahren.\n\nï± Wird der Anmeldeprozess kÃ¼nftig Ã¼ber TAF/TAP TSI konforme Nachrichten laufen ?\n\nJa, das ist bei der Trassenanmeldung zum Netzfahrplan vorgesehen, denkbar wÃ¤re es auch fÃ¼r die Umwandlung der RV-KapazitÃ¤ten in RV-Bezugslinien.\n\nï± Wie kann der bisher aufwÃ¤ndige Prozess der Angabe der RV-KapazitÃ¤tsnummern bei der NEP-Trassenanmeldung vereinfacht werden ?\n\nDer Verweis auf die RV-KapazitÃ¤tsnummer ist auch kÃ¼nftig bei der NEP-Trassenanmeldung nÃ¶tig; wir prÃ¼fen jedoch, inwieweit hier Vereinfachungen durch IT-\n\nUnterstÃ¼tzung und eine andere Gestaltung der RV-KapazitÃ¤tsnummern mÃ¶glich sind\n\nDB InfraGO AG | FAQ | RV 2029 | 06.03.2026\n\n14",244,"{\"canonical_url\":null,\"normalized_sha256\":\"be18472ef30ae3aed260463030e44efd73dfcd43ca5e0c280190b62e898a4216\",\"page\":14,\"source_id\":\"src_e92671a89ddb058a405f\",\"source_sha256\":\"545243d1b72e2160d47fe8bc317a41ce2e373d16726f5ed48dfbb6ea5afe36b5\",\"source_version_id\":\"sv_1bc23f87d1aeef8eae02ebb3\"}","1631bcd04a7febd99d7a638ed3e40f5f7171a0f8b10c4a858b755aa15d7bcda8"],["chunk_a55f218c07f80c2ec314717b","wiki/sources/glossar-zvf-data.md",0,"Seite 1","DB InfraGO AG\n\nI.IBF 4\n\nUnterjÃ¤hriger Fahrplan und Baubetriebsmgmt.\n\nAdam-Riese-StraÃŸe 11-13\n\n60327 Frankfurt am Main\n\nhttps://www.dbinfrago.com/web\n\nAbkÃ¼rzungsverzeichnis ZvF (Art der Arbeiten)\n\nhttps://www.dbinfrago.com/web\n\nKurzbeschreibung Langbezeichnung\n\nBkProbe Blockprobefahrten\n\nBrÃ¼ Arb BrÃ¼ckenarbeiten\n\nBrÃ¼Pr BrÃ¼ckenprÃ¼fung\n\nBstg Arb Bahnsteigarbeiten\n\nBÃœ Arb Arbeiten am BahnÃ¼bergang\n\nCoN Container\n\nDu Arb Durchlassarbeiten\n\nDua Gl W Durcharbeitung Gleise und Weichen\n\nDuaGl Durcharbeitung von Gleisen\n\nDuaW Durcharbeitung von Weichen\n\nFels Fels-/Hangsanierung\n\nGA Gleisauswechslung