INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_c95b7258b0e197908fc0872e","wiki/sources/rahmenvertrag.md",0,"Aktuelles","Die beabsichtigten und unterrichteten Ã„nderungen zu RahmenvertrÃ¤gen wurden im Beschlusskammerverfahren zurÃ¼ckgenommen. Wir planen die WiedereinfÃ¼hrung von RahmenvertrÃ¤gen zur Netzfahrplanperiode 2029. Eine entsprechende unterjÃ¤hrige Ã„nderung der INB 2027 mit dem Zeitplan und den Eckpunkten eines weiterentwickelten Vergabemodells wird am 12. Dezember 2025 gemÃ¤ÃŸ Â§ 19 Abs. 6 ERegG vorlÃ¤ufig in Kraft gesetzt und zur Stellungnahme verÃ¶ffentlicht.\n\nAktuelle VerÃ¶ffentlichungen\n\n- **[VerÃ¶ffentlichung der INB 2027 sowie der Entgelte fÃ¼r Serviceeinrichtungen 2026 / 2027](https://www.dbinfrago.com/web/aktuelles/kund-inneninformationen/kund-inneninformationen/2025-KW50-inb-2027-entgelte-se-2027-13700642)**\n- **[Stellungnahmeverfahren zu unterjÃ¤hrigen Ã„nderungen der INB 2027](https://www.dbinfrago.com/web/aktuelles/kund-inneninformationen/kund-inneninformationen/2025-KW50-stellungnahmeverfahren-inb-2027-13700824)**",78,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/nutzungsbedingungen/rahmenvertrag-11916868\",\"normalized_sha256\":\"0b0401e5425ed911d7f14239cd6501189773ec2c55746e00abfb39f240427532\",\"page\":null,\"source_id\":\"src_67784974dc879eeff939\",\"source_sha256\":\"84435cc2db77dbdf9d0f74e69e0a4ea6dd2038d2615b9a1c22d145eafd5f75c0\",\"source_version_id\":\"sv_e3ffbc367584b6746788d07c\"}","45d13589b0f0837834bd289d5c36fa662e99cbb2936308c398f5fc768c78b7d3"],["chunk_96bb90a29411fccebfe36eb1","wiki/sources/rahmenvertrag.md",1,"Umgang mit neuen RahmenvertrÃ¤gen (Planungsstand Herbst 2025)","Die DB InfraGO AG schlÃ¤gt aufgrund von Kund:innenwÃ¼nschen den Abschluss von neuen RahmenvertrÃ¤gen fÃ¼r die Netzfahrplanperioden 2028 â€“ 2032 vor (neue vierte Rahmenvertragsperiode). Die hierfÃ¼r vorgesehenen Nutzungsbedingungen wurden im August 2025 mit dem Entwurf der INB 2027 zur Stellungnahme verÃ¶ffentlicht (vgl. nebenstehenden Link). Anfang September 2025 fanden zudem zwei Online-Vertiefungsveranstaltungen zur geplanten WiedereinfÃ¼hrung der RahmenvertrÃ¤ge statt. Die in diesen Veranstaltungen prÃ¤sentierten Chart-Unterlagen stellen wir Ihnen in nebenstehendem Link ebenfalls zur VerfÃ¼gung.",71,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/nutzungsbedingungen/rahmenvertrag-11916868\",\"normalized_sha256\":\"0b0401e5425ed911d7f14239cd6501189773ec2c55746e00abfb39f240427532\",\"page\":null,\"source_id\":\"src_67784974dc879eeff939\",\"source_sha256\":\"84435cc2db77dbdf9d0f74e69e0a4ea6dd2038d2615b9a1c22d145eafd5f75c0\",\"source_version_id\":\"sv_e3ffbc367584b6746788d07c\"}","8b1cf2ed7df70b2464a286066386e20e499950ad805bae7fb9931d4d2782f012"],["chunk_8553f77b052e977c31727d15","wiki/sources/rahmenvertrag.md",2,"Umgang mit bestehenden RahmenvertrÃ¤gen","Eisenbahnverkehrsunternehmen und alle anderen Zugangsberechtigte, die bereits RahmenvertrÃ¤ge abgeschlossen haben, kÃ¶nnen diese gemÃ¤ÃŸ Â§4 Muster-Rahmenvertrag Ã¤ndern.\n\nDie Ã„nderungen oder auch auÃŸerordentliche KÃ¼ndigung bestehender RahmenvertrÃ¤ge muss vorbehaltlich etwaiger behÃ¶rdlicher oder gerichtlicher Verfahren spÃ¤testens bis zum Ablauf der Trassenanmeldefrist des Netzfahrplans erfolgt sein, sofern die Wirkung zum jeweiligen Netzfahrplan erlangt werden soll. NÃ¤here Details zu den Anmeldungen und den Fristen enthalten die Ziffern 4.2 und 4.4 der Nutzungsbedingungen Netz (NBN), die Sie Ã¼ber den nebenstehenden Link einsehen kÃ¶nnen.",76,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/netzzugang-und-regulierung/nutzungsbedingungen/rahmenvertra